/* 2024年4月16日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"r06-20240416-9","dateIso":"2024-04-16","title":"2024年4月16日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6657#one","fetchedAt":"2026-08-14","characters":64143,"voices":[{"i":1,"speaker":"つる委員長","text":"○午後 １時００分開会\nただいまから文教委員会を開会いたします。\n本日は、お手元に配付しております審査・調査予定表のとおり、幹部職員の異動について、請願・陳情審査、報告事項、および、その他を予定しております。\n本日も、特に報告事項等が多くなっておりますので、効率的な委員会運営にご協力をよろしくお願いいたします。\n本日は２名の傍聴申請がございますので、ご案内いたします。また、その中で１名の方から録音申請が出ておりますので、これを許可いたします。\n────────────────────────────────────────────\n１ 幹部職員の異動について"},{"i":2,"speaker":"つる委員長","text":"それでは、予定表１、幹部職員の異動についてを議題に供します。\n本件につきまして、理事者よりご紹介願います。"},{"i":3,"speaker":"米田教育次長","text":"それでは、教育委員会事務局の異動者についてご紹介させていただきます。\nまず、舩木庶務課長でございます。"},{"i":4,"speaker":"舩木庶務課長","text":"庶務課長の舩木です。よろしくお願いいたします。"},{"i":5,"speaker":"米田教育次長","text":"続きまして、荒木学校施設担当課長でございます。"},{"i":6,"speaker":"荒木学校施設担当課長","text":"学校施設担当課長、荒木です。よろしくお願いいたします。"},{"i":7,"speaker":"米田教育次長","text":"続きまして、河内品川図書館長でございます。"},{"i":8,"speaker":"河内品川図書館長","text":"品川図書館長の河内でございます。よろしくお願いいたします。"},{"i":9,"speaker":"米田教育次長","text":"教育委員会の異動者については以上でございます。よろしくお願いいたします。"},{"i":10,"speaker":"佐藤（憲）子ども未来部長","text":"それでは、私から子ども未来部の幹部職員の異動についてご報告させていただきます。\nまず私自身になりますが、４月１日付で子ども未来部長を拝命いたしました佐藤でございます。どうぞよろしくお願いいたします。\n続きまして、原児童相談所担当部長でございます。"},{"i":11,"speaker":"原児童相談所担当部長","text":"児童相談所担当部長、原です。よろしくお願いいたします。"},{"i":12,"speaker":"佐藤（憲）子ども未来部長","text":"次に、柴田子ども施策連携担当課長心得でございます。"},{"i":13,"speaker":"柴田子ども施策連携担当課長","text":"柴田でございます。子ども計画を担当させていただきます。よろしくお願いいたします。"},{"i":14,"speaker":"佐藤（憲）子ども未来部長","text":"次に、染谷子ども家庭支援センター長・子ども家庭センター開設準備担当課長兼務でございます。"},{"i":15,"speaker":"染谷子ども家庭支援センター長","text":"染谷です。引き続き、児童家庭相談事業、ヤングケアラー支援などを所管いたしますが、併せて、子ども家庭センターの開設に向けた準備を担当させていただきます。よろしくお願いいたします。"},{"i":16,"speaker":"佐藤（憲）子ども未来部長","text":"次に、長谷川児童相談課長でございます。"},{"i":17,"speaker":"長谷川児童相談課長","text":"長谷川でございます。令和６年１０月開設に向けて、児童相談所の運営・開設準備を行ってまいります。よろしくお願いいたします。"},{"i":18,"speaker":"佐藤（憲）子ども未来部長","text":"次に、金子一時保護担当課長でございます。"},{"i":19,"speaker":"金子一時保護担当課長","text":"金子でございます。１０月に開設します児童相談所の一時保護所を所管します。よろしくお願いします。"},{"i":20,"speaker":"佐藤（憲）子ども未来部長","text":"続きまして、芝野保育入園調整課長でございます。"},{"i":21,"speaker":"芝野保育入園調整課長","text":"芝野でございます。よろしくお願いいたします。区内の保育所の入園相談、利用者助成、指導検査、区立保育園の改築・大規模改修等を所管いたします。よろしくお願いいたします。"},{"i":22,"speaker":"佐藤（憲）子ども未来部長","text":"次に、中島保育施設運営課長でございます。"},{"i":23,"speaker":"中島保育施設運営課長","text":"中島でございます。区立保育園・幼稚園の管理・運営などを所管してまいります。どうぞよろしくお願いいたします。"},{"i":24,"speaker":"佐藤（憲）子ども未来部長","text":"最後に、佐藤保育事業担当課長でございます。"},{"i":25,"speaker":"佐藤（裕）保育事業担当課長","text":"佐藤でございます。私立保育園・幼稚園を所管いたします。よろしくお願いいたします。"},{"i":26,"speaker":"佐藤（憲）子ども未来部長","text":"以上でございます。どうぞよろしくお願いいたします。"},{"i":27,"speaker":"つる委員長","text":"ありがとうございました。どうぞよろしくお願いいたします。\n以上で本件を終了いたします。\n────────────────────────────────────────────\n２ 請願・陳情審査\n(1) 令和６年陳情第２１号 品川区の人工芝マイクロプラスチック流出問題について具体策を求める陳情\n(2) 令和６年陳情第２２号 校庭の人工芝生化をする時の周知方法について見直しをしてほしい陳情"},{"i":28,"speaker":"つる委員長","text":"次に、予定表２の請願・陳情審査を行います。\n請願・陳情審査の(1)令和６年陳情第２１号 品川区の人工芝マイクロプラスチック流出問題について具体策を求める陳情および(2)令和６年陳情第２２号 校庭の人工芝生化をする時の周知方法について見直しをしてほしい陳情につきましては、関連する内容のため、一括して議題に供します。\n進め方としまして、２件の陳情について一括して説明、質疑を行い、その後、２件の陳情の取扱いについて、１件ずつ、各会派のご意見を確認したいと思いますので、よろしくお願いいたします。\nまず、これら２件の陳情は初めての審査でありますので、書記に朗読させます。\n〔書記朗読〕"},{"i":29,"speaker":"つる委員長","text":"朗読が終わりました。\nそれでは、本件につきまして、理事者より一括してご説明願います。"},{"i":30,"speaker":"荒木学校施設担当課長","text":"それでは、陳情第２１号の件についてご説明いたします。\n初めに区立学校の人工芝の整備状況でございますが、これまでに、小学校、中学校、義務教育学校を合わせまして合計２２校で整備いたしました。\n整備の目的は大きく３点ございます。１つ目に近隣環境への配慮、２つ目に安全な運動環境の確保、３つ目に校庭の効率的な活用でございます。これらの目的の達成を目指しまして、学校改築時や既存校庭の改修時に合わせ、整備を進めております。\n実際に人工芝生化した学校におきまして児童・生徒を対象にアンケートを実施したところ、約８割より好評を頂きました。けがの抑制や、膝や足への負担軽減、雨上がり後の使用性向上における評価が特に高くなってございます。このことから整備の成果があったものと認識しております。\n次に、人工芝の流出の現状把握でございます。職員により人工芝の校庭の状況を確認いたしましたところ、学校間で差異はございますが、校庭の周囲や排水溝の中に人工芝の抜けを確認しております。これらの人工芝の流出対策でございますが、３点の対策に現在取り組んでおります。１つ目に、小まめな日常清掃でございます。校庭の周囲や出入口、排水溝内において、定期的に学校側で清掃を行っております。２つ目に、抜けにくい人工芝の採用です。人工芝生化に際して、各メーカーの最新の製品仕様を確認して、耐久性が高く、抜けにくい製品を選定し、設計に反映して工事の発注を行っております。３つ目に、下水道流出を抑制するフィルターなどの設置です。排水溝から下水道に接続する部分に、抜けた人工芝を捕捉するフィルターなどの設置を進めております。これらの対策については、環境省が推奨している方法とも合致すると考えてございます。流出抑制につきましては、今後も新工法や新素材などに関する情報収集に努めてまいりたいと思います。\n続きまして、陳情第２２号の件についてご説明いたします。\nまず、人工芝生化に際しての周知方法でございますが、学校改築に当たりましては、学校から保護者に対して、ＰＴＡ役員会、保護者会、学校だよりなどにより周知をいただいております。教育委員会といたしましても、学校と連携しながら、保護者説明会などにより情報周知を図っております。\nまた、ご指摘の建設準備懇談会は決定機関ではございません。学校改築計画につきまして、地元に情報を提供し、意見を伺う場として位置づけております。学校施設の整備内容については、施設間の均一性や学習指導の一貫性を担保するために、教育委員会として決定しております。なお、こちらの懇談会では常に最新の情報を提供していますので、計画の進捗に応じて大きく変更が生じる可能性があります。都度変わる情報に、児童や保護者、生徒、区民の方々に混乱が生じないよう、非公開としております。\nこのような中で、児童・生徒の意見の取り入れについては、学校と相談しながら内容を検討し、実施しているところです。例えば、改築校により、シンボルツリーなどの樹木の選定や、階段や廊下、トイレの内装の色決め、外壁のアクセントカラーの色決めなどを行っております。子どもたちが毎日目にする学校の印象的な部分において、主体的に学校整備に参加できるような仕組みを考えております。"},{"i":31,"speaker":"つる委員長","text":"説明が終わりました。\nこれより一括して質疑を行います。\nご質疑等がございましたら、ご発言願います。"},{"i":32,"speaker":"安藤委員","text":"まず幾つかお伺いしますが、まず陳情第２１号の理由の１・２行目に書いていますが、「将来的に区内の全ての小中学校のグラウンドが基本的に人工芝生化する」ということですけれども、区教育委員会はそういう方針を持っているのでしょうか。持っているとすれば、理由は何なのでしょうか。もし持っているとしたら、一律に全部やるというのは再検討すべきと、この陳情にも書いていますけれども、私は再検討すべきだと思いますが、いかがでしょうかというのが１つ。\nそれと、一足制の話と人工芝生化ということがリンクしているのではないかと思うのですけれども、今後、一足制にするということには人工芝が必要という関係なのか。両者の１対１の関係なのでしょうかというのが２点目。\n３点目は、流出対策をしているという話もありましたが、それで防げるとは思えないのですけれども、それで流出というのは防げているのでしょうか。どういう認識なのでしょうか。伺います。お願いいたします。"},{"i":33,"speaker":"荒木学校施設担当課長","text":"まず、教育委員会の人工芝の整備方針でございますが、冒頭申し上げましたとおり、３つの大きな目的です。近隣環境への配慮、こちらは具体的には砂ほこりの影響を最小限に受け止めるというところでございます。２つ目の安全な運動環境の確保というところに関しましては、児童・生徒のけがの抑制・防止というところの観点がございます。３つ目、校庭の効率的な活用というところでは、雨上がりにすぐに校庭を使えるということで、より体力向上に資するような運動状況を展開できるというところで、教育委員会としても、今後も全ての改築校・既存校において人工芝は整備していきたいと考えております。\n２つ目の、一足制に関する人工芝の関係性でございますが、まずは人工芝の整備が先にありまして、人工芝整備によりまして靴が汚れないといったメリットがございますので、結果として一足制に移行しているという状況でございます。\n一足制につきましても、今、試験運用をしておりまして、その中で、児童・生徒、あとは教職員の方々から意見をいただきまして、実際に導入するかどうかというところを、現在、学校において判断していただいているという状況でございます。\n３つ目の流出対策でございますが、こちらは１００％、完全に流出を防ぐことはまず不可能であろうとは考えております。しかしながら、先ほど申し上げた３点の対策、特に日常の清掃対策というところをしっかり行っていきまして、長期的には抜けにくい人工芝の採用、あとは流出を抑制するフィルターの設置を進めまして、可能な限り流出抑制を進めていくという方向で進めております。"},{"i":34,"speaker":"安藤委員","text":"私の認識不足だったのか、区教育委員会が全ての学校に人工芝を整備していくという方針を持っているというのは、私は認識がなかったのですけれども、それはいつ決定したのでしょうか。いつ、そういう方針を定めたのでしょうか。私はそれは行き過ぎだと思いますので、見直していただきたいと思っているのですけれども、学校によって様々環境も違いますし、通われる方の意見もありますので、そういうことを一律でやっていくというのは違うのではないかと思うので、伺います。\nそれと、一足制については、今のご説明ですと、一足制は一足制、人工芝は人工芝ということ、完全にリンクしているものではないのかという、それはそれでというふうに聞こえたのですけれども、こちらは当該校であるならば、一足制なのだけれども人工芝を導入しないということはあり得るのでしょうかという質問をします。\nそれと、流出対策については、随分率直な答弁だと思ったのですけれども、取りあえず可能な限り防ぐのですが、メリットのほうが大きいので進めていきますというふうに聞こえたのですけれども、関連資料も出されていますし、Ｓｉｄｅｂｏｏｋｓにも入っていますけれども、様々な環境への影響というのが指摘され、アメリカに至っては、州によっては、ボストン市では都市公園に新たに人工芝を設置しないように命じたというような欧米の動きもある中で、随分、いけいけどんどんをやっていると思うのですが、区教育委員会の、人工芝の環境への影響、ＰＦＡＳも含めた環境や人体への影響はどのように考えているのでしょうか。改めて認識を伺わせていただきたいというのが３つ目です。\nお願いします。"},{"i":35,"speaker":"荒木学校施設担当課長","text":"まず人工芝生化の方針につきましては、教育委員会としては整備を進めていきたい方針は持っておりまして、既存校改修・改築工事実施時に、学校とまずは相談しているところでございます。中学校などですと、部活動の種類によっては、人工芝よりも土の舗装のままがいいといったご意見もございますので、そういったところでは相談しながら決めているという状況はございます。\n２点目は、基本的に一足制の場合は、校舎内の汚れが非常に気になるところかと思いますので、まずグラウンドの舗装として、汚れない人工芝であったり、人工芝に替わって汚れないような舗装であれば、その際に一足制が可能であろうと考えております。\n３点目の、人工芝の環境・人体への影響というところにつきましては、陳情の資料にもありますように、やはり一定、人体への影響はあるものとは考えております。ですが、こちらのようなデメリットも含めて検討した上で、流出対策をしっかりと行っていき、その上で、人工芝のメリットというところが非常にたくさんございますので、こちらを推し進めていきたいという考えでございます。"},{"i":36,"speaker":"安藤委員","text":"人工芝を全ての学校に整備していくという方針というのは、いつ区教育委員会は持ったのでしょうかという質問をしたので、そこは答えられる方も含めて答えてもらいたいのですけれども、区教育委員会としては、こういう方針をこのときに持ちましたというのが知りたいのですけれどもというのが１つです。\nもう一つは、一足制については、今の２回目のご答弁を聞くと、やはり人工芝というのは一足制を入れる上での不可欠の条件だということになるということですので、先ほどの私の認識を改めました。かなり関係しているということだと思いました。\nそれと、環境についてですけれども、これまた何というのでしょう、それでいいのでしょうかというのを私は思います。といいますのは、やはり、数ある、先ほどいろいろ学校の環境について、子どもの意見や当事者の意見は聞いていますという話も冒頭にありまして、外壁のアクセントカラーなどという例がありましたけれども、これは子どもが遊ぶ場所ですから、それが、人体に多少影響があるということがあるのに、メリットのほうが大きいから進めるということでいいのか。私はそうはならないと思いますけれども、人工芝を全部のところに区が推し進めていくという方針は撤回したほうがいいのではないかと私は思いますが、いかがでしょうか。やはり学校の環境というのは、こちらにも、子ども権利条約が聞かれていますけれども、これからは本当に、子どもに関わる施策については当事者の声を聞くということがスタンダードにならなくてはいけないということだと思いますので、建設準備懇談会のメンバーや開催の在り方あるいは役割は、意見を伺う場ですという話でしたけれども、もう少し権限も広げる必要があるのではないかと思いますし、メンバーを広げる必要があると思います。子どもの声を、人工芝化するかしないかということに、きちんと反映させる意味でも、建設準備懇談会のメンバー、開催の在り方、位置づけについて、工夫する必要があると思うのですけれども、いかがでしょうか。"},{"i":37,"speaker":"荒木学校施設担当課長","text":"まず１点目の人工芝の方針につきましては、教育委員会といたしましては、まずは推進していきたい方針というところです。こちらも、先ほども申し上げましたとおり、各学校と、当然、メリット・デメリットも含めて協議しながら、ぜひ進めてほしいというところで、各学校とも整備を進めているところでございます。\n２点目の環境への影響というところにつきましては、やはり１００％阻止ということは難しいと考えておりますので、まずはしっかりと流出対策を行っていく。長期的には、より抜けにくい人工芝の採用、各メーカーとも廃プラスチックを削減できるような商品開発に取り組んでおりますので、そういった新素材・新工法を取り入れながら、日常の維持管理をしっかりと行っていくというところで考えております。\n３点目の建設準備懇談会でございます。建設準備懇談会の構成員としては、ＰＴＡの役員、あとは地域コーディネーターといった方々からも参加をいただいております。こちらについては、保護者、あとは児童・生徒と直接接点のある方々にも出席していただいているという認識でございます。ですので、そういったところから児童・生徒の意見を吸い上げていただければ、教育委員会としてもしっかりと意見として受け止めて検討していきたいと考えております。"},{"i":38,"speaker":"米田教育次長","text":"最初のご質問の、教育委員会が人工芝生化の方針をいつ持ったのかというようなところでございますけれども、先ほど担当課長からもお話ししておりますように、様々な、人工芝で活動をすぐ再開できるなどというメリットもありますけれども、品川区の非常に、住居が近隣にあるというところでは、かねてより砂ぼこりに対する、風が吹いたときの苦情等もございまして、そのようなところのデメリットが一定程度、削減されるというようなところもございます。そういった意味で、近隣や、実際にお子さんの活動の再開や、学校の活動のしやすさだったりというところを勘案して、現在、人工芝生化するほうがメリットがあるという考えに立っているところでございますが、全ての学校を人工芝生化するという方針を持っているわけではなく、改築等の状況に応じて、人工芝のほうが基本的には優れているという認識の下、改築の方向性を進めているということでございます。そういった意味では、限りなく１００％に近く人工芝生化されていくメリットがあると考えてはございますが、いつ方針を定めたというものではございませんので、そちらは補足させていただきます。"},{"i":39,"speaker":"安藤委員","text":"分かりました。機械的に全ての学校の芝生にするという方針を持っているわけではないということなのですが、ただ、基本的には優れているということなのですが、やはり、事は子どもの健康に関わることなので、しかも直接、教育環境に触れるようなところに当たる部分のことなので、私は、非常に環境問題に対する目というのも鋭くなっていますし、あと、様々な知見というのも新たに分かってきているというところもありますので、今、次長がおっしゃったようなところであっても、やはり一旦、立ち止まって、その方針は区民と一緒に考える必要があるのではないかと思います。なので、それまではそういうことだったかもしれないですけれども、様々やはり環境や人体への害悪が分かってきているわけですから、そこは本当に、まず可能な限り流出を防いで技術の進展を待つという姿勢ではなく、むしろ一旦立ち止まって、導入はストップして、本当に技術革新が起きたら、そのときに導入を考えようかというスタンスのほうが私はいいのではないかと思いますが、これは意見です。\n最後に２点だけ質問したいのですけれども、この陳情にもあるように、今後、人工芝を導入される際というのは、そのメリット・デメリットについて、やはり説明する機会、メリットだけでなく、こういう研究結果もありますということを、デメリットも含めて当事者に説明する機会を持つべきだと、こちらの陳情にも書かれておりますが、私もそう思うのです。そういうものは最低限、やっていただけるのでしょうか。そういう機会を持つつもりはあるのでしょうかというのが１つ。\n２つ目は、当該校において、決定までの、もう少しプロセスを知りたい、お聞かせいただきたいというか、先ほど、決めるのは区教育委員会ですという話でしたけれども、では当該校においては人工芝というのはもう決定されたのか。それを決定したのは区教育委員会だと思うのですけれども、いつ決定になったのか、その決定に至るまでに、建設準備懇談会を含めて、どういう意見聴取があったのかというあたりを、最後にお聞かせいただきたいと思います。"},{"i":40,"speaker":"荒木学校施設担当課長","text":"１点目のメリット・デメリットの説明でございますが、こちらはしっかりと行っていきたいと思っております。メリットだけではなく、デメリットもしっかりと説明した上で、学校児童・生徒などの意見を取り入れ、計画に反映していきたいと思っております。\n２点目の、決定までのプロセスでございますが、まず結論から申し上げますと、当該校では人工芝生化が決定しております。この過程でございますが、建設準備懇談会をはじめ、児童・保護者への説明というところでございますが、こちらが、令和元年１１月に保護者説明会を実施しております。その際に、人工芝の計画概要について説明しておりまして、人工芝も含めて説明しているところでございます。その後も、こちらは既存在校生の方、保護者向けの説明ではあるのですけれども、この保護者説明会の後に、新入生の保護者を対象とした説明会も毎年度開いておりますので、その際にも、新校舎で人工芝生化するというところは説明しております。\nしかしながら、開催の時期や説明した方法によっては、なかなか届かなかったということも考えられますので、それについては今後しっかりと、学校と情報周知の方法、意見聴取の方法を相談しながら進めていきたいと考えております。"},{"i":41,"speaker":"つる委員長","text":"ほかにございますか。各委員、よろしいですか。"},{"i":42,"speaker":"吉田副委員長","text":"いろいろご説明ありがとうございます。今までのメリットの中で、確かに近隣への配慮というのは、ずっと砂ぼこりについては気になっているところで、それは何とかしなくてはいけないという認識は私も持っております。\nただ、人工芝生のマイクロプラスチック化について、議会の中にこれを持ち出したのは、たしか生活者ネットワークかと思います。この陳情文の中にある、あべ祐美子議員の調査活動については、たしか、せお議員も参加させていただいて、その時点で、あべ議員も、生活者ネットワークがマイクロプラスチックの問題を人工芝生に絡めて持ち出したときには、そこまでではないのではないかというのは正直思われたとおっしゃっていました。ただ、調査の中で現に目黒川から、マイクロ人工芝生由来だというものが、その場でも発見されたということがあって、やはり人工芝。これは校庭には限らないです。いろいろなところで人工芝生化が進んでいますので校庭には限らないのですけれども、人工芝生というものが、今、世界中で問題になっている環境中へのプラスチックの流出ということに寄与しているのは間違いがないのではないかと思います。\n今、いろいろ調査結果はあると思いますけれども、ある調査によれば、人はみんな１週間にクレジットカード１枚分ぐらいのプラスチックを摂取している。それは、だから子どもたちも同じ状況ですし、そういう状況なわけです。もう、母乳からも検出されているという状況です。恐らくこれはもう、環境問題としてだけではなく、健康問題、これからの将来的な子どもたちの体に影響する問題として捉えるべきなのではないかと私自身は思っております。\nそれで、基本、あまり賛成ではない方向なので、調べてもそういう情報が私のところには当たってしまうのだと思いますけれども、今まで化学物質の問題でいろいろ意見をいただいている、アドバイスもいただいている、東京農工大学の高田秀重先生が、最初はいろいろ化学物質のことを教えてくださったのですけれども、だんだんその先生自身のご関心がプラスチックの問題のほうに移っておられて、大変、問題視されて、警鐘を鳴らしておられます。それで、その先生のご説によると、人工芝にはノニルフェノールなどの環境ホルモンも入っている。それで、私が検索した限りでは、これに反論する情報が見られなかったのですけれども、何か、「これはそんなことはないよ」というような情報はお持ちでしょうか。ご承知のとおり、ノニルフェノールは環境ホルモンと言われた化学物質で、メダカの雌化を確認した化学物質です。今、いろいろな少子化対策というのもあって、政策面でもいろいろ必要だと思いますけれども、やはり子どもができにくくなっているという状況は確かなのではないかと思います。そういうことに、こういう化学物質も影響しているのではないかと私は個人的には懸念しておりますが、この高田先生の学説に反論するような情報など、どなたかお持ちだったら教えていただきたいのですけれども、いかがでしょうか。"},{"i":43,"speaker":"つる委員長","text":"所管で分かっているところで。今の質問は、この陳情の趣旨と本筋からは少しあれなので、承知しているところで、分かる範囲でご答弁いただければと思います。"},{"i":44,"speaker":"荒木学校施設担当課長","text":"ノニルフェノールという物質に関する資料については、手元の資料ではないのですけれども、今後、人工芝に使われる素材にどのような物質が含まれているのかというところはしっかりと調べてまいりまして、採用する際には、しっかりと教育委員会の中でも確認した上で対応していきたいと考えております。\n環境への問題については、今後も動向を注視しながら採用を進めていきたいと思っております。"},{"i":45,"speaker":"吉田副委員長","text":"所管から外れるといえば外れるのですけれども、人工芝生を語るときに、これを認識せずに選ばれてしまったら少し困ると思ったので伺いました。\nそれで、この人工芝生の発注は、品川区の教育委員会としてということでいいのですか。どの事業者に発注しているかという資料は庶務課から出していただいたのですけれども、具体的な、どういう芝生を指定しているかというところまでは、その情報からは得られなかったのですけれども、その指定の方法などはどのようにされているのか。一つ一つの事業者については伺わなくていいです。教育委員会として、こういう人工芝生を、工事を発注するときに、どの辺を条件として芝生を選んでいるかなどということがありましたら教えていただきたいので、お伺いします。"},{"i":46,"speaker":"荒木学校施設担当課長","text":"教育委員会として人工芝の学校グラウンドを整備するときの発注方法でございますが、発注段階に図面におきまして人工芝の一定の仕様を指定しております。具体的には、芝の長さや、あとは充填剤の有無を指定しております。現在であれば、小学校は長い芝で充填剤がないもの、中学校であっても、球技のバウンドなどの影響がございますので、短い芝で充填剤がないものという指定をした上で発注いたしまして、業者が決まりましたら、施工業者が、仕様に見合った部材はこういったものですよといった提案を、我々教育委員会で受けます。その上で、教育委員会としてその性能、仕様を確かめた上で、場合によってはサンプルを取り寄せたり、既に整備してある施設に視察に行ったりしまして、しっかりと見て決定しているという形で進めております。"},{"i":47,"speaker":"吉田副委員長","text":"結局、情報公開請求が必要なのかと思いますけれども、それぞれの事業者にどういう、仕様書面でしょうか、どういうものを発注されているかというのは、できたら学校のグラウンドに関しては、文教委員会に情報提供していただけると大変ありがたいと思います。今後の情報提供の在り方についてはいかがでしょうというのと、それから、これまでハイブリッドという、高価になるのは承知しているのですけれども、天然芝と人工芝のハイブリッドというものも随分開発されていて、私たちが最初に主張した頃に比べると、それも改良されて価格面でもだんだん下がっているのではないかと思うのですけれども、その辺の情報は、学校の人工芝生化について何か検討されていることがあったら伺いたいと思います。全然、もうハイブリッドは高いから最初から駄目ということであれば、その点についてもお答えください。"},{"i":48,"speaker":"荒木学校施設担当課長","text":"まず文教委員会の情報提供ということに関しましては、可能な限り、情報提供はしていきたいと考えております。どういった人工芝を植えるのかといった点で情報提供はしていきたいと考えております。\n２点目のハイブリッドは、人工芝と天然芝のハイブリッドというところかと思いますが、やはりこちらは、費用面やメンテナンス性という面におきましては、プラスチック製の人工芝のほうに今現在は優位性があると考えておりまして、現在は採用は見送っているところでございます。今後また技術開発などによりまして、価格面や耐久性、メンテナンス性で優れてきましたら、こういった製品も採用していく可能性があると考えております。"},{"i":49,"speaker":"吉田副委員長","text":"それから、あと流出を防ぐためには、これは前から承知しているのですけれども、排水溝の小まめなお掃除ということが言われておりまして、それは具体的にはどういう方がどういう頻度でされているか。学校ごとなのであれば、それは校長の判断になるのでしょうか。そのような一定のルールというのと、それから、確かに小まめに掃除することは環境からいったらすごく必要なのですけれども、一方で、働く方への業務の低減という意味では、小まめにすればするほど大変だと思うのですけれども、その辺については、どのように今行われているか伺います。"},{"i":50,"speaker":"荒木学校施設担当課長","text":"清掃頻度でございますが、こちらは学校の用務に主に清掃を行っていただいております。こちらは、主に校庭の出入口、特に校庭と昇降口が接するような部分につきましては、ほぼ毎日清掃をいただいております。校庭周囲は週数回程度、排水溝に関しましては、雨の状態などにもよりますが、月１回程度というところでお願いしております。これに加えまして、数年に１度は専門業者によるメンテナンスなどにも入っていただいているという状況でございます。"},{"i":51,"speaker":"吉田副委員長","text":"分かりました。学校としては精いっぱいのことをしていただいているということかと思います。あとは人工芝を採用するかどうかというような問題になるかと思いますが、芝生の選定の仕方や発注についてはしっかりされているということですので、引き続きその点については本当に、価格面は予算が絡むことなので難しいところはあると思いますが、その辺については子どもたちの健康や環境への問題、環境への問題も結局は、将来的には、今の学校に行っているような子どもたちが大人になったときの環境に影響がありますので、多分その頃、私はもう死んでしまっていないのですけれども、子どもたちの将来ということをぜひ重点に置いて、いろいろな選定や対策は打っていただきたいと思います。これは要望に留めます。以上です。"},{"i":52,"speaker":"つる委員長","text":"ほかにございますか。\nほかにご発言がないようですので、これで質疑を終了いたします。\nそれでは、まず、令和６年陳情第２１号の取扱いについて、ご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらかご発言願います。また、結論を出すのであれば、その結論についてもご発言ください。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":53,"speaker":"せお委員","text":"本日結論を出すで、不採択でお願いします。\n先ほどご答弁がありましたとおり、日常清掃だったり、抜けにくい人工芝を採用したり、あとフィルター設置ということで、今、環境省が紹介しているような対策を取っていただいていると思って、引き続きそちらをやっていただきたいと思っています。\nあとは、一部の学校になるのですけれども、学校の状況によって、結構、排水溝などが所管をまたいだり、学校のものではないもののほうに流れてきたりして、そちらの清掃ができていなかったりといったものもあったりするので、その辺は、所管をまたいで連携もしながら、ぜひ清掃、フィルター設置なども考えて検討していただきたいというのは要望しておきます。以上です。"},{"i":54,"speaker":"ゆきた委員","text":"本日結論を出すで、不採択でお願いします。\n人工芝のマイクロプラスチックの流出に関しては、日進月歩で改良されているものを選定しているとのことで、ここは環境に即して、今後もよりよいものを選定していただきたいと思います。また事実として、小まめな清掃、学校での最終ますからの排水溝のネット対策として二重の対策を取られていることや、環境省のサイトで紹介している項目については区でも対応を取られている点など、陳情で求められている点については既に対策が取られていることを確認させていただきましたので、あえてこの陳情について取り上げる必要はないと思われますので、不採択とします。以上です。"},{"i":55,"speaker":"吉田副委員長","text":"先ほど申しましたけれども、校庭やグラウンドの人工芝生の問題については、たしか最初に区議会の中で問題視したのは生活者ネットワークだと思っております。その視点からいうと、本当は、本来であればやはり天然のもの。それで、私が一番気になるのは、将来の子どもたちを取り巻く環境です。子どもたちが健やかに生きられるような環境であってほしいということです。ただ、現時点では、教育委員会として、またそれぞれの学校として、対策をしっかり取られているということと、それから人工芝生の選定につきましても、いろいろ、きちんとした対応をされているということを確認いたしました。会派としての協議の結果といたしましては、この陳情に関しましては、きちんとこれからも対策を取っていただく。それから、先ほどの化学物質の問題は、所管が外れたとしても子どもたちの問題ですので、ぜひその辺については知見を深めていただきたいと思います。やはり私は少子化の一因であるのではないかと考えておりますので、ぜひその辺も併せて検討をお願いしたいと思います。それをやっていただくことを前提に、この陳情については不採択といたします。以上です。"},{"i":56,"speaker":"安藤委員","text":"本日結論を出すで、採択です。\nやはり現役の、実際に通っているお母さんですか、保護者から、こういった陳情が出されたということで、しかもかなり現在進行形で、すごく、実態としてこういう声が、心配する方というのがいるということです。それで、人工芝のアンケートを取ったら８割の方は好評とありましたけれども、逆に言うと２割の人は、こういうものを心配されている可能性もあるわけです。私は、この陳情はすごく重いのではないかとは思っています。\nその上で今回、この項目の中で、流出対策実施と、あと十分な説明、丁寧に説明ということですので、いずれにしても、まだまだ不十分だと思いますので、これはさらに、流出は完全には防ぐことができないという話もありましたけれども、であるならば、なおさら、こういったことはさらに前に進める必要があると思いますので、私は、この陳情を採択して、しっかり最低限の対策は取らせるということが必要だと思います。"},{"i":57,"speaker":"高橋（し）委員","text":"本日結論を出すということで、不採択でお願いします。説明で、３点に及び、対応しているということがありましたので、流出対策を取っているということですので不採択とさせていただきます。\nその中で、ほかの委員もお話しされていましたけれども、人工芝の中でもどんどん技術革新が進んでいるので、採用する際には、その点においては費用がかかったとしても、しっかりと、質のいいといいますか、そういうものを選択していっていただきたいということと、フィルターも同じだと思います。フィルターについても、かなり防止に資するものが出ていると伺っていますので、そちらもお願いしたい。これは要望ということで、この陳情に関しては、区で現状、進めていることは納得できましたので。"},{"i":58,"speaker":"石田（し）委員","text":"結論を出すで、不採択でお願いします。\n理由としては、今、様々質疑・答弁の中でも、いろいろと対策は講じていただいているということなので、引き続きしていただき、さらには、いわゆるメリットは十分にあると。しかし、若干デメリットもないわけではないので、やはりデメリットの部分はできる限り解消に向けて、ぜひ、さらに取り組んでいっていただければと思います。\nあと、いろいろ今お話が出て、天然芝、ハイブリッド、様々、技術革新の中でいいものを取り入れていっていただきたいという各委員の要望は、私は、はっきり言って、お金はかかるのかもしれないのだけれども、これを採用しない限り、今いろいろ作られている方たちというのは費用が下がっていかないのです。皆さんが使うから、どんどん価格も安くなっていく。これはもう当たり前の話なので、私はやはり、これは品川区だけではなくて、例えば東京都全体での教育委員会ならびに学校関係者の中でも、こういったことに取り組んで、本来は国がやるべきことですけれども、そういった技術に対しても、やはりしっかり予算をつけることによって、さらに環境にも健康にもいいものというのが安価で安く作られていって、供給できるようになってくるのだと思うので、これは本当にそういった意味では、品川区教育委員会が、こういったことを皮切りに、ぜひ積極的に東京都内の学校関係者ならびに文部科学省に対しても、そういった取組、予算をしっかり取るようにということで東京都や国に対しても要望していくのが、一番、品川区が採用するときに、いいものを採用できるのではないかと私は思うので、ぜひその辺は新たに取り組んでいっていただければと要望しまして、不採択ということでお願いします。"},{"i":59,"speaker":"つる委員長","text":"それでは、本陳情については、結論を出すとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":60,"speaker":"つる委員長","text":"それでは、本件は本日結論を出すことに決定いたしました。\n先ほど、それぞれの方のご意見を伺いましたので、本陳情については挙手により採決を行います。\nそれでは、令和６年陳情第２１号 品川区の人工芝マイクロプラスチック流出問題について具体策を求める陳情についてお諮りいたします。\n本件は挙手により採決を行います。\n本件を採択とすることに賛成の方は、挙手願います。\n〔賛成者挙手〕"},{"i":61,"speaker":"つる委員長","text":"賛成者少数でございます。\nよって、本件は不採択と決定いたしました。\n次に、令和６年陳情第２２号の取扱いについてご意見を伺いたいと思います。\n継続にする、あるいは結論を出す、どちらかご発言願います。また、結論を出すのであればその結論についてもご発言ください。\nそれでは、品川区議会自民党・無所属の会からお願いいたします。"},{"i":62,"speaker":"せお委員","text":"本日結論を出すで、不採択でお願いします。\nこちらもご答弁にあったように、ＰＴＡや保護者会やお便りなどで周知しているということでありましたし、あとは、特定のメンバーで話し合うと書かれているのですけれども、特定のメンバーというのは、私としては感じていない。いろいろな方からお話を聞いているのかと思いました。子どもたちの意見というのはすごく大切ですし、あと、環境問題ということ全体として、子どもたちと話し合ったり、勉強していくということはすごく大切だと思うので、そういったことをやっていただいているので、引き続き、そちらもやっていただきたいのですが、校庭の地面を何にするかということの決定を子どもたちがするというのは少し難しいのかと思っているので、広く意見を聞いた上でということを、引き続き教育委員会にはお願いしたいと思っています。以上です。"},{"i":63,"speaker":"ゆきた委員","text":"本日結論を出すで、不採択でお願いします。\nご説明、答弁の中でもあったように、学校からも、保護者会、ＰＴＡ役員会、あと近隣の接点のある方、地域の接点のある方、学校地域コーディネーターを呼んで、意見・情報収集を行って実施している点を確認させていただきました。また、学校側からも人工芝に関して歓迎する声を多く聞いている現状であり、こういった学校側からの声というのも、日常的に児童と関わる教職員の肌感覚で行われていると思われますし、それが前提での学校側からの声として反映されていると思われますので、この陳情に関しては不採択でお願いいたします。"},{"i":64,"speaker":"吉田副委員長","text":"本日結論を出すで、不採択でお願いいたします。\n子どもたちの意見などについても、さんざん今まで生活者ネットワークとしても、子どもたちの意見を聞いてほしい。それで、意見なので、決定の場に参加というのは、確かに、せお委員のおっしゃったとおり、なかなか責任も生じますので難しいかと思います。\nそれで、子どもたちの意見を聞くというのが、現場に行ってみて、やはり分かれるのです。だから、多分、意見を持っているのが、自分たちの意見を聞いてくれそうな大人のところに、いろいろ言っていくので、どういう子どもたちが誰に意見を言っていくかということで分かれるのかとは思っております。ただ、私たちが直接聞く子どもたちからの声は、例えば、夏はとにかく人工芝が熱いということや、スライディングしたときにやけどをしそうになるというご意見。また一方で、やはり転んだときに安全だという意見も聞いたという声も聞きます。だから、一概に子どもたちの声といっても、もっと丁寧に聞き取っていく必要があるかと思います。子どもたちの意見を聞くということは、懇談会にいろいろなメンバーが参加するということのほかに、先生方がいろいろな場面で本当に子どもたちの声を聞いて、それがきちんと教育委員会での政策に反映されるような形の、風通しのよさというのでしょうか、そういうものも今後求めていきたいと思います。それはしっかりやっていただくということを前提に、この陳情については不採択といたします。"},{"i":65,"speaker":"安藤委員","text":"本日結論を出すで、採択でいいと思うのですけれども、決定するに当たっての、やはり情報公開の在り方や、当事者の意見をきちんと聞いてくださいということだと思うので、すごく当たり前なことを言っているのではないかと思いますし、あと、質疑の中でも、区は何もやっていないとは、もちろん言いませんけれども、本区はやっていますというご答弁はありましたけれども、そうはいっても届かない方もいらっしゃいますということでしたので、それはそうなのでしょうけれども、これは意識的に、子どもたちが自分たちをめぐる環境について、大人たちが声を聞いてくれているという体験を通して、物事が決まっていくという過程そのものがかなり教育効果もあると私は思いますし、それは生徒指導提要にも書かれていることなのですけれども、そういったことを身近なところから進めていくという意味では、非常に重要な取組になるのではないかと思いますし、現状が十分だとも思いませんので、これは採択すべきだと思います。"},{"i":66,"speaker":"高橋（し）委員","text":"本日結論を出すということで、不採択でお願いします。\n陳情項目が陳情者の方から挙げられていますが、それについての説明があって、承知いたしました。周知の方法について、それから建設準備懇談会ですか、その在り方についても説明があったので、そのような状況から、現状でしっかりと進められていると思います。\nただ、子どもが関わるということに関しては、幾つか具体例を挙げていただいたのですけれども、まださらに幾つかの形で、新しい学校などに活かせる、人工芝ということではなくて、そういうアイデアがきっと、逆に児童・生徒にあるかもしれませんので、そういうところを吸い上げて、当該地区などに、あるいは学校生活に反映させていく。先ほどからある、子どもたちの意見を聞くというふうに、今、話がありますので、一歩進んで、様々な場面で聞いていっていただきたいと思います。"},{"i":67,"speaker":"石田（し）委員","text":"結論を出すで、不採択でお願いします。\n理由は、ご答弁の中でも、既に品川コミュニティ・スクールという枠組みの中で、様々なところの代表者の方からも声を聞きながら一緒に進めているということだと思うので、そこは理解しましたし、また引き続き、そこはやっていただきたい。特に、今の時代、情報発信と意見の受信というものは、もう芝生化などのみならず、やはりコミュニティ・スクールとして、様々な方からしっかりと意見を受信しながら、その方々に、できる限りの情報発信というものは、引き続き努めていただきたい。そこは要望しておきますけれども、この陳情に関しては不採択でお願いします。"},{"i":68,"speaker":"つる委員長","text":"それでは、本陳情については、結論を出すというとのご意見でまとまったようでございますので、そのような取扱いでよろしいでしょうか。\n〔「はい」と呼ぶ者あり〕"},{"i":69,"speaker":"つる委員長","text":"それでは、本件は、本日、結論を出すことに決定いたしました。\n先ほど、それぞれの方のご意見を伺いましたので、本陳情については挙手により採決を行います。\nそれでは、令和６年陳情第２２号 校庭の人工芝生化をするときの周知方法について見直しをしてほしい陳情を採決いたします。\n本件は挙手により採決を行います。本件を採択とすることに賛成の方は挙手願います。\n〔賛成者挙手〕"},{"i":70,"speaker":"つる委員長","text":"賛成者少数でございます。\nよって、本件は不採択と決定いたしました。\n以上で、請願・陳情審査を終了いたします。\n────────────────────────────────────────────\n３ 報告事項\n(1) 「品川区学事制度審議会 答申」について"},{"i":71,"speaker":"つる委員長","text":"次に、予定表３の報告事項を聴取いたします。\n(1)「品川区学事制度審議会 答申」についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":72,"speaker":"柏木学務課長","text":"説明に入ります前に、学事制度審議会の中間答申の件につきましては、私の認識不足により委員の皆様には大変ご迷惑をおかけしました。この場をお借りしておわびを申し上げたいと思います。今後このようなことがないよう気をつけてまいりますので、よろしくお願いします。申し訳ございませんでした。\nそれでは、品川区学事制度審議会答申についてご説明をいたします。資料をご覧ください。本日は資料として、こちらに記載の４種類を配付してございます。\n初めに、２枚目になりますが、第７回および第８回品川区学事制度審議会の実施報告について、ご説明いたします。\n令和６年２月１９日に第７回、３月１４日に第８回の審議会を開催しております。第７回、第８回とも、最終答申等について審議を行い、第８回で答申の決定をしております。答申決定後は、委員長から教育長への答申の手交を実施しております。\n続きまして、答申の内容について説明いたします。\nまず、資料「品川区学事制度審議会答申 概要版」で説明をいたします。\n概要版を１枚おめくりいただきまして、こちらには「はじめに」で、品川区の就学人口の状況や課題、審議会の設置目的、「品川区学事制度審議会とは」では審議会の委員構成、「品川区立学校全体の児童・生徒数の推移および推計値」では区立学校の児童・生徒数の状況を記載しております。児童・生徒数の推計ではございますが、児童数は今後も増加し、一時的に減少するものの、令和１９年度まで増加する推計となってございます。生徒数も児童数と同様、令和２２年度まで増加する推計となっております。\n次に、３ページの上段になりますが、審議会への諮問内容についてでございます。諮問内容は、１つ目に、安定的に児童・生徒を受け入れる態勢を確保するための方策、２つ目に、今後の学校改築の考え方となってございます。\n次に、審議会の提言の概要についてです。答申で提言した内容は、諮問内容の１、安定的に児童・生徒を受け入れる態勢を確保するための方策については、ページ中段の「審議会の考え方」で記載のとおり、1)から3)に該当する場合は通学区域の変更などもやむを得ないと示されております。1)から3)の考え方につきましては、後ほど答申自体の説明の際に改めて説明をさせていただきます。また、経過措置についても提言が示されておりまして、適切な経過措置を柔軟に検討することと示されてございます。\n諮問内容２「今後の学校改築の考え方」につきましては、適切な情報収集のほか、社会情勢の変化なども踏まえ、より綿密な推計を行うこと、また学校の立地や地域性を考慮して教室の増減に幅を持たせた計画を進めることと示されております。\n以上が、概要版での答申の説明となります。\n続きまして、資料「品川区学事制度審議会 答申」をご覧ください。\nこちらは２ページ目から、審議会設置の背景といたしまして、設置の経緯、小学校における３５人学級の制度化、本区の就学人口推計の変化、本区の学級増にかかる対応について記載してございます。\n５ページ目からは、審議会としての議論の方向性を記載しております。今回の審議会では、前回の審議会の答申の下、制度設計された学校選択制や、中学校の通学区域に関する考え方を尊重した上で議論を進めることが確認されております。また、５ページ以降、参考として前回審議会による提言について記載してございます。\n続きまして、７ページからは、通学区域内の就学人口の受入れが困難な学校について記載してございます。こちらに表がございますが、表の説明については８ページ目に記載がございますけれども、こちらは簡単に、このページでご説明いたします。表の区分「顕著」は、就学人口の増加が進み、また学級増が続いていることから、現在の校舎では就学人口を受け入れきれない可能性が非常に高い学校を示しております。現状では、城南小学校となります。区分の「不足が想定」は、一時的に教室不足が見込まれる学校、または令和１１年度以降に教室不足が想定される学校を示しております。こちらは、今後の就学人口の動向を注視していくこと、また未改築校については改築の対応も考慮する必要があると示されております。なお、こちらで令和１１年度以降と分けて書いているところの理由でございますが、こちらは、人口推計をした段階では、令和１０年度までは、既に生まれていて住民登録があるお子さんを基に推計を行っている。令和１１年以降につきましては、まだ生まれていないお子さんになりますので、そういうことで分けて考えているところでございます。区分「受入可能」でございますが、現在の推計では教室不足は発生しないと想定されている学校を示しておりますけれども、引き続き就学人口の動向を注視していく必要があると考えてございます。\n続きまして、９ページ目では、パブリックコメントを受けての審議会の議論についてを記載しております。こちらは、記載のとおりではございますけれども、パブリックコメントでいただいた意見について審議会でも議論し、一部、答申で修正を行っているところでございます。\nまた、ページの下段から、審議会の提言について記載しております。先ほど概要版で提言のお話をしましたけれども、こちらで、先ほど言いました1)から3)の内容について、もう少し詳しく説明をしたいと思います。こちらは記載１０ページになりますので、１０ページをお開きください。\n１つ目となります。1)就学人口推計において、数年の間学級増が継続している、または見込まれる場合についてです。こちらは、数年の間学級増が継続する場合、既存校舎において普通教室を確保することが困難となる可能性が高くなり、現時点では普通教室の増設により対応できたとしても、数年のうちに限界に達することが想定されるという考えでございます。なお、ページの下段のほうで、なお書きに記載がございますが、審議会では、校舎の増築や学校外施設の活用などについても検討いたしました。校舎の増築は、可能な学校については有効な手段となりますが、増築できない学校も多く、区全体の方針として示すことは困難という結論に至っております。また、学校外施設の活用については、そもそも近隣に活用できる施設があるのか。また、児童・生徒の安全の確保、教職員への負担等の観点から、現実的ではないという結論に至っております。学校の新設についても、記載の内容のとおり、現実的ではないという結論に至っております。\n続きまして、2)普通教室の転用元として特別教室を活用する際、その特別教室の移転先を既存校舎内に確保することができない場合です。児童・生徒を受け入れるうえで、適切な教育環境の整備が必要となります。学校教育を運営するために通常備えるべき教室についても極力整備する必要があり、それらを整備することができない状況で普通教室を増設し続けることは望ましくないという考えでございます。\n3)就学人口が増加する地域を一定程度特定することができる場合です。就学人口の増加を通学区域の変更によって対応する場合、効果的な区域を設定する検討をする必要があります。通学区域内の就学人口に偏りがあるなど、就学人口の増加地域を一定程度特定することができる場合においては、通学区域の変更による対応に効果があるだろうと考えてございます。\nなお、先ほどの繰り返しになりますけれども、適切な経過措置を柔軟に検討することが示されております。\n１３ページからは参考資料を掲載しておりますが、すみませんがまたページを飛びまして１９ページからは、推計に基づく品川区立学校の想定不足教室数の推移を記載しております。表の見方でございますが、グラフの縦軸の０は、各学校の確保教室の最大値を示しております。それより上にグラフがある場合は教室不足を示しております。縦軸の０またはそれより下にグラフがある場合は、教室不足ではないことを示しております。こちらは、中学校区ごとに各学校の状況を示してございます。\n続きまして、２２ページには、国が示す校舎に備えるべき教室等を記載しております。既存校舎に普通教室を増やす場合は、こちらに示されている教室を確保しながら、教室の転用や工事を行っております。\n答申自体の説明は以上となります。\n続きまして、資料「品川区学事制度審議会（中間答申）パブリックコメントご意見と回答について」です。\nパブリックコメントにつきましては、昨年の１２月１２日から本年１月１０日までの３０日間実施し、区民の方からの意見等を受け付けておりました。意見提出者は８人、意見総数は３１件となっております。意見のカテゴリーといたしましては、普通教室の確保、学校改築に関する意見が最も多く、続いて、学校選択制、就学人口推計に関する意見となっております。いただいた意見と回答につきましては、資料に記載のとおりとなります。こちらも繰り返しになりますが、審議会ではこちらの意見については一件一件審議いたしまして、答申の一部修正を行ってございます。\n答申等の報告は以上となります。今後ですが、答申やパブリックコメントのご意見と回答等につきましては、４月２１日号の広報と、区のホームページに掲載いたします。また、区政資料コーナーや品川区立図書館でも閲覧できるようにしてまいります。また、こちらの答申につきましては、町会長会議等でも説明していきたいと考えてございます。\n最後になりますが、今後、答申の提言を基に、学事制度について検討、制度設計をしてまいります。現在は改めて全学校の就学人口の確認作業を行っております。また、今後、未就学の兄弟等の情報も収集しながら、経過措置についても検討してまいります。"},{"i":73,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":74,"speaker":"安藤委員","text":"概要版の１番「安定的に児童・生徒を受け入れる態勢を確保するための方策」というところの、「審議会の考え方」というところで、通学区域変更がやむを得ない場合はこの３つですと書いてあるのですけれども、そこで1)、2)、3)とあるのですが、これはそれぞれ、どこの学校なのか聞きたいと思います。それと、それは本文に書いてあるのかというのを含めて教えていただきたいと思います。\nそれと、２番の「今後の学校改築の考え方」というところでの「審議会の考え方」というところですけれども、「開発計画を適切に情報収集する」とありますけれども、これまでもやってきたとは思うのですが、どういうやり方で情報収集をされているのでしょうか。また新たなやり方でも考えておられるのか。この点と、同じ記述のところの、「より綿密な就学人口の推計を必要に応じて行うことが求められます」と書いていますけれども、これについても、「より綿密な」というのは、今までの推計と何か変わるのでしょうかというか、どういう意味なのかというのを教えてください。お願いします。"},{"i":75,"speaker":"柏木学務課長","text":"まず１つ目の、「安定的に児童・生徒を受け入れる態勢の確保の方策」の1)から3)はどこの学校かということでございますが、こちらにつきましては、どこの学校ということではなく、こういうことがある場合は通学区域の変更もやむを得ないという方針を示しているものになりますので、審議会において、この学校はこれだということを審議したものではございません。\n２つ目の、改築の関係で、情報収集の方法と、あと綿密な就学人口の推計の件でございますが、情報収集といたしましては、これまでも開発計画等の戸数ですとか、そういうものをいただいていますので、そういう部分での情報収集というのは今までどおりというところではございます。ただ、就学人口のほうでございますが、今回、改めて昨年度、就学人口の推計をしてございますが、やはり就学人口の推計というのは、年度がたつにつれ、その確度が下がってくる、低くなるという部分がございますので、適切な時期に、また就学人口の推計等を取りながら、また当然、既に住民登録がある方の実際の人口というものを見ながら、より綿密に検討していくということを示しているものでございます。"},{"i":76,"speaker":"安藤委員","text":"分かりました。\nそうですね。最初のところですけれども、「就学人口が増加する地域を一定程度特定することができる場合」というのは3)にあるのですけれども、現時点でこういうのは、どこかないのですかということなのですけれども、これからこういうことに照らして、この３つの基準、考え方、方針に照らして、今、どこなのだろうというのを特定している段階なのか。その辺を少しお伺いしたいのと、最後の後ろのページには、これから反映ということで、具体的な制度の見直し作業を進めますとなっているのですが、今そういうことを進めているのでしょうか。この具体的な制度の見直し作業を進めるというのは、いつぐらいのスケジュール感を考えているのでしょうか。\nまとめてしまいます。パブリックコメントにも報告がありましたけれども、中間答申に対するパブリックコメントが８人・３１件出たのですが、これによって中間答申が修正された箇所などというのは何かあったのでしょうか。伺います。"},{"i":77,"speaker":"柏木学務課長","text":"１つ目の学事制度の件でございますけれども、こちらは今、具体的にどこがこれに当たるのかというのは、改めて就学人口の見直しを全学校についてかけているところでございますので、具体的な学校につきましては今後という形になりますが、答申でも示させていただいていますが、城南小学校については近々に対応せざるを得ないかということは思ってございます。\n見直しのスケジュール感でございますが、これも今、就学人口は、全学校の確認作業を行っていますので、それを基に今後、スケジュールを決めていくこととなりますが、変更する必要がある場合につきましては、もちろん早めに決めて、保護者等、地域等には早めに周知していきたいと考えてございます。\nパブリックコメントを受けての修正の部分でございますが、パブリックコメントでの大きな修正はございませんでした。しかしながら、パブリックコメントをいただいた内容で表現の方法を変えたりという部分では対応してございます。具体的には、７ページの、本文の６行目で、「人口動向によって確度が低くなる可能性があります。」などでは、パブリックコメントをいただきまして表現を変えているところでございます。ほかにも何か所か、そういう形で表現を変えているところがございます。あと、経過措置につきましては、当然、審議会でも、経過措置については重要だということは認識しておったのですが、パブリックコメントも受けまして、こちらも、「地域の実情を考慮して、適切な経過措置を柔軟に検討する」というふうに内容を補強した形で表現を変更してございます。"},{"i":78,"speaker":"安藤委員","text":"同じ７ページなのですけれども、「顕著」というのは、学校選択を今停止している状況ですけれども、「不足が想定」というところが出ていますけれども、ここが学区の変更という認識という、大体そのような大まかな理解でいいのか、教えてください。\nそれと、あとパブリックコメントなのですが、パブリックコメントで結構いろいろ意見が出ていましたけれども、例えば大きな１番目のナンバー４やナンバー８など、統廃合で今まで学校が結果的に少なくなっているではないですか。それで教育環境が壊れてしまったとか、小・中学校をこれまで減らしてきたではないかみたいな意見があるのですけれども、結構、率直な指摘かと思うのですが、区教育委員会としては、これまで学校を統廃合したということがありまして、その後に今現在の教室不足、学校不足を招いたということにもなると思うのですけれども、そういった率直な指摘についての政策的な反省というのはあるのでしょうか。それとも、それはそれ、これはこれという考えなのでしょうか。伺いたいと思います。"},{"i":79,"speaker":"柏木学務課長","text":"以前、小中一貫校の際に、小学校などを統合しているということはございますけれども、現在の教室不足等は、そちらとは直接はリンクしないと考えてございます。正直、今、「顕著」で出しております城南小学校につきましては、周りで統合しているという事実はございませんし、「不足が想定」のところも、直接、統合の影響を受けたとは考えてございません。\nそれと、一番最初に質問がございましたが、「不足が想定」が学区の変更をするところかということですけれども、こちらについては、可能性もあるし、しないかもしれないという部分でございます。現状で今、繰り返しになりますけれども、改めて就学人口の全学校の見直しをしているところでございますが、その結果を受けてからの判断となってございます。"},{"i":80,"speaker":"安藤委員","text":"今の区教育委員会の認識は分かりました。聞いたことで分かるので、よかったです。\nそれと、学区の変更というのは、やはりすごく、地域にとっては物すごい影響があると思うし、思い入れも強いところです。地域をつくっているのが学校なわけですから、かなり丁寧にというか、説明を、ありきで進めるのは困難ではないかと思いますので、そこは、地域の意見を聞きながら柔軟に、具体化の方針は見直すなどといったことが必要なのではないかと思いますので、それについては最低限、やっていただきたいと、要望です。\n質問の最後は、やはり、パブリックコメントの意見などを見て、そうだと思ったのですけれども、そうですね。やはり、さらなる社会情勢の変化がこれからあるのではないかということで、今回、３５人の小学校のみで考えていて、なおかつ学校選択制も変えないということを前提にしてやっているわけですが、校舎を置いておいたとしても、学級規模がこのままいくのかという。もう、今からこういった大きな制度設計をするのであれば、もう少し先を見据えた、しかもその変化というのは、子どもたちの教育環境にとってはいい変化なわけですから、３０人学級の制度化というのを見据えて方策を立てるべきなのではないかと思うのです。それは、少なくとも中学校までの３５人学級というのは、今、実現していないのですが、小学校まではやっていて中学校をやらないというふうには絶対ならないと思うのです。国でも議論していますし、区独自に、今のうちから中学校はもう３５人にしてしまって、これから報告もありますけれども、区独自教員をどんどん採用して、品川区から中学校は３５人をまずやるのだ、国を動かすのだというぐらいの勢いで、必ず近い将来、３５人になると思うのです。それぐらいは見据えたほうがいいのではないかと思うのですけれども、それはぜひ、今から具体的な試算も行って、中学校は３５人に対応可能な方策というのを立てるべきだと思うのですけれども、その考えはあるのでしょうか、ないのでしょうか。伺いたいと思います。"},{"i":81,"speaker":"柏木学務課長","text":"中学校での３５人学級の考えでございますが、こちらは、我々が学級編制をする際には、法律に基づいての話になりますので、法律がそうなっていないものを想定として、それを進めていくという考えは持ってはございません。また、独自教員につきましても、独自教員は、別に３５人学級ですと、やはり、先ほどありました３０人学級を実現するために区が独自で採用しているものではございませんので、あくまでも学級編制につきましては、国の標準法に基づいて考えていきたいと考えてございます。"},{"i":82,"speaker":"安藤委員","text":"実際にいつも、独自教員の話をするとそうなるのですけれども、目的はどうあれ、実際にクラスを分割するときに、充てていたりしているわけです。それは、過去の答弁からも、区教育委員会からも出ているのですけれども、それを活用できるということはもう明らかですので、なおかつ子どもたちの教育環境にとってプラスになるわけですから、しかも、中学校もいろいろ、いじめや不登校など大変ではないですか。だから私は、先を見据えて、学校給食無償化のように、品川区から、区教育委員会から、子どもたちのことを考えて先進的な施策を打っていくという立場で、ぜひ今回は最初から３５人ということを念頭に置いて検討していただきたいと、改めて要望いたします。"},{"i":83,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":84,"speaker":"ゆきた委員","text":"昨年の７月の文教委員会では、学校、地域、保護者への周知を経て、令和７年度の新入学予定者から新制度の運用開始を目指すとありました。これから通学区域等の具体的な新制度設計が進められると思われますが、令和７年度に向けての今後のスケジュール感というか、先ほど安藤委員からも話があって、少し重なるところがあると思われますけれども、あと１年間で、何月までにはどこまで持っていくといったスケジュール感について、紹介できる範囲でお聞きできればと思います。また、今回資料として出されている、品川区学事制度審議会の答申の概要版は、学校側にも紹介の配布等がされているのか。この点の２点についてお聞きしたいと思います。"},{"i":85,"speaker":"柏木学務課長","text":"順番が逆になりますけれども、学校への周知の件でございますけれども、５月の校長連絡会を通じて説明・周知していきたいと考えているところでございますが、現時点では、まだ学校に概要版等は配布はしてございません。\n今後のスケジュールの件ではございますが、以前、説明した際に、最短ですと令和７年度入学者からという、最短の場合の話をさせていただいたつもりでございます。今、令和７年度からいくのかどうかというのは、まだ教育委員会としては最終的な確認を取っているものではございませんが、令和７年度に実施するに当たっては、遅くとも学校選択の周知をするまでには決定しなければいけない。それの物の印刷等を考えれば、少なくとも７月には制度も決めて、もちろん、その際には説明等もする必要があると考えてございます。"},{"i":86,"speaker":"ゆきた委員","text":"品川区の現状と難しい課題については、保護者なども、今後入学を予定している保護者の理解と納得があってこそ、初めて乗り越えられるものだと考えられますので、ぜひ、きめ細かな周知をお願いしたいと思います。また、今後の予定についても順次、紹介していただければと思います。こちらは要望で終わりたいと思います。"},{"i":87,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。"},{"i":88,"speaker":"吉田副委員長","text":"概要版のほうで、ぱっと目についたので概要版で、めくって右側のページで、「今後の学校改築の考え方」の「審議会の考え方」で、「開発計画を適切に情報収集するほか」と書かれております。この開発計画を適切に情報収集というのがすごく大事だと思っていて、それが、だから就学人口が増加する地域を特定することにつながるのかと思います。それで、情報収集といいますと、教育委員会の側が積極的に収集するなのですけれども、私は何かもう少し連携があってもいいのかと常々思っているのです。それで、この間、近隣の学校の卒業式や入学式に参加させていただいたときも、私が参加した学校については、もう町会長も、「あそこにも建つだろう、あそこにも建つだろう」ということで、「それがみんな、うちの、この学校の校区なんだよね。あそこなんか、隣の学校のほうが近いのにね」と言いながら、やはり一番身近な、自分たちの地域の小学校についての教室の不足、あとは特別教室を使うしかないし、それから先生の配置も大変厳しくなるということで、結構皆さん、地域の方たちもこの辺は関心があって、情報収集だけではなくて、もう少し、開発に限らず、建設計画というのでしょうか、そういうことを、所管との連携というのはもう少し考えられないものなのかと思うのですが、その辺についてはいかがでしょうか。"},{"i":89,"speaker":"柏木学務課長","text":"副委員長が言いましたとおり、どこに何が建つという情報なのですけれども、こちらは所管から、２０戸以上のファミリータイプの計画がある場合につきましては、教育委員会にその情報が来るように、もう既になってございますので、そういう部分では十分、ほかの部署とも連携しながら、そういう情報収集はしているところでございます。副委員長からありましたように、あそこに建つのだという話は我々も地域から聞いたりしますが、それが、正直言いまして、分譲なのか賃貸なのかによっても、就学児童の発生が全然違うものですから、そういう部分の情報も含めて、関係課からは情報をいただくようになってございます。"},{"i":90,"speaker":"吉田副委員長","text":"２０戸以上については情報が来るというのは、前も伺っていて、知っているのですけれども、逆に、もうこの辺のエリアだと、公立学校でいうと、もういっぱいいっぱいだみたいな、それが、私の希望的なあれで言うと、そちらの状況が、品川区内のいろいろな建設関係のほうに、何というか、計画の見直しや、今後の計画を立てる参考にならないのかと思っているのです。やはり、私は転勤族で子育てをいたしましたので、こういう報告を見ると、本当にちくちくくるのです。やはり、転勤族も一定、ご迷惑をかけていて、もう学校に入ってしまって親しくなると、次の転勤はいつ決まるのかと。「決まるときは早く言ってね。先生の配置などに関係するので」という、本当に地域の方たちにはご迷惑をかけながら転勤せざるを得ないという状況でやってきたので、地域でずっと学校を見守ってこられた方たちにとっては本当に、転入者、それから転出者はすごく関心が高いところなのかと思います。\nそういう意味では、もう少し教育委員会のほうが、学校の適切な運営のために、この辺はもう建てられても学校の受入れもいっぱいいっぱいだみたいな。先ほどのは、「建設するから、要は教育現場は何とかしてね」という情報ではないですか。そうではなくて、反対側の情報提供で、建設計画のほうに影響を与えるような連携の仕方というのは無理なのでしょうかというのが常々の疑問なものですから、その点についていかがでしょう。こういう審議会の中では、そういうご意見は一切出ないで、やはり開発計画ありきで学校を何とかするというのが前提なものなのでしょうか。その点について伺いたいのですが、いかがでしょうか。"},{"i":91,"speaker":"柏木学務課長","text":"最初に、副委員長からありました転入などは全然悪いことではございませんので、区といたしましては、子どもが増えることは非常にいいことだと考えておりますので、そういうふうに言わないでいただきたいと思います。\n計画についての件でございますけれども、計画をいただいたとき、情報をもらったときに、これは以前も文教委員会で少しお話ししたかと思いますけれども、教育委員会から意見を言うことができます。当然、その意見をどう受けるかというのは、デベロッパーなりのものになりますけれども、最近もございまして、詳しくは言えませんけれども、結構厳しく、教育委員会としては意見を述べさせていただいているところでございます。審議会でも、できるところだけの通学区域を変更するなどというのはできないのかという意見はあったことはありました。"},{"i":92,"speaker":"吉田副委員長","text":"決して、私もやむを得ず引っ越しはしておりましたので、出て行くなと言われても難しいし、入ってくるなというのを言われても困るし、言われた覚えもないのですけれども、でも、やはり地域の方たちにしてみたら、転出者・転入者に対しての、教育環境が変わっていくということについては敏感にならざるを得ないのだということも十分理解しておりますし、今こういう立場になって、こういうことを検討する中では、やはりそういうことも考えられないのかと思いました。\n今、結構、厳しめに意見を言うこともできると言われたので、それはよかったと思うのですけれども、今後もぜひ、やはり開発ありきではなくて、教育現場が、転入者にとって適切な教育環境を確保するためにも、こういう計画を見直してほしいというような意見が言えるような状況は確保していただきたいと思います。\nこれは要望にとどめます。以上です。"},{"i":93,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":94,"speaker":"高橋（し）委員","text":"すみません。幾つか。\n１つ目は、私の聞き取り不足なのですが、確認させていただきたいのですけれども、現在、人口の推計の綿密なる調査をしている。その結果が出たら、出た段階で学区の変更等をする。それからもう一つ、改築に関して、幅を持たせた計画をしていくという、まず、大きな流れはそれでよろしいですか。"},{"i":95,"speaker":"柏木学務課長","text":"そうですね。委員の言うとおり、今、就学人口のまた再確認をしますので、その結果で、正直、もう物理的に学校として受入れが不可能な場合は、通学区域の変更も視野に検討すると。その際には、どこを変えるのかというのも含めて検討する必要がございます。それで、学校改築は少しまた別の話にはなると思うのですけれども、当然、学校改築を検討する際には、就学人口を基に、ある意味、増減も含めて幅を持たせて検討していくという形になると思います。"},{"i":96,"speaker":"高橋（し）委員","text":"ということは、今もう本当に入りきらなくなる、上回るところの中で言えば、特に「顕著」というところで城南小学校なのだと思うのですけれども、今、前回の審議会の結果からやっている、前回の制度変更が継続中であるわけですよね。ということは、大きくは変えるわけではなくて、当面、幾つか、特に城南小学校があれだと思うのですけれども、そこについて今年度、令和７年度にやるように読み取れているのですけれども、そうならそうでいいのですけれども、そういうことがはっきりと書いていないので、該当されるというか、関連するところの方々は、非常に不安に思っている部分があるのかと思うのが１つ。\n逆に言うと、城南小学校を含め、そこだけではなくて、もっと大きく変えていく。将来の人口推移を考えながらする予定で考えているのかという、そこはいかがでしょうか。"},{"i":97,"speaker":"柏木学務課長","text":"学区の変更の件でございますが、就学人口の推計を出していますけれども、当然、将来的なものはどうしても、ずれが大きくなってくるということもございます。今現在、この推計を基に、区内の学区域を大きく変えるという考えはございません。\n今、就学人口の確認をしていますが、今回、通学区域の変更をする場合は、当該校の通学区域だけを変更するという形になりますが、単純に、この学校はもう物理的に無理なので通学区域を変更する必要があるとなった場合でも、逆に言うと、変える先の学校の学校規模などというのも検討しなければいけませんので、そこは慎重に検討する必要があるのかとは考えてございます。"},{"i":98,"speaker":"高橋（し）委員","text":"そういうふうにご説明していただくと分かるのですけれども、このチラシをもらった保護者の方は、一体、審議会が終わると何をするのかと思うのです。それはなぜかというと、「審議会の考え方」とあって、「やむを得ないと考えます」とか、あと、「求められます」とか、そういう表現なのです。これは、審議会の文言だからそうなっているのでしょうけれども、これは一体、それでどうするのかという点で見ると、具体的な制度の見直しを、作業を進めます。それは何かとなるのです。だから、保護者の方に配るわけですから、もともと審議会の諮問内容というのは、誰がどういう方というのは書いていないのですけれども、これをもらって、当事者の方も、そうでない方も一体というのもあるのですけれども、どうも印刷してしまったのであれなのですけれども、説明が必要なのかと思ったりしたのですが、それについてはいかがですか。"},{"i":99,"speaker":"柏木学務課長","text":"審議会の答申は、どうしても言い方として、やはり区内全域の話になってくるので、個別具体的にここがこうですという話ではないので、そういう意味ですと、ある程度説明をしなければ、今後の方向性というのですか、今後についてはご理解は難しいかというのは、ご指摘を受けると、そのとおりかと、正直思うところでございます。こちらは、今後説明するときには、その辺は少し気をつけながら、あと具体的な、ある意味、制度等についても説明をしていきながら、一緒に併せて説明していく必要があるのかというのは、今お話も伺いながら、そう感じているところでございます。"},{"i":100,"speaker":"高橋（し）委員","text":"それをよろしくお願いします。\nもう一つだけ。先ほど、教室が足りないというお話なのですけれども、普通教室をどう確保するかというのはもちろんなのですけれども、それに伴って、特別支援学級の部屋が多くなったり、あるいは特別支援教室の指導する場所が少なくなったり、さらには今度、不登校の児童・生徒を指導する場所が必要になってくるわけです。だから、そういうことも含めて、どれだけ足りないかということを考えていく必要があると思うのですけれども、単純に、在校生が何人で教室が幾つという以外の、その結果、例えば教室が足りなくて少人数の授業をやっていない学校もあるわけです。教室が足りなくて、できなくなってしまうから。そういうことも含めると、やはり教室増減に幅を持たせるという部分はあるのですけれども、そういうことも、普通教室以外のいろいろな必要な場所というのですか、教室等を考えて、改築なり、今後の学校の増設など考える必要があると思うのですけれども、その点はいかがでしょうか。"},{"i":101,"speaker":"柏木学務課長","text":"委員のご指摘のとおりだと思います。答申の２２ページ、資料６で、ここは小学校のことを書いていますけれども、国が示す、校舎に備えるべき施設というのがございますので、当然、こういう教室は必ず確保しながら、学校改築や普通教室の増設等については、これを基準に進めていくという考えでございます。"},{"i":102,"speaker":"高橋（し）委員","text":"そうなのです。そうやっていただいているのはいいのですけれども、それができなくて、何というか、指導に影響が出ているところもあるので、当然、法律上幾つか準備しなくてはいけないところは必要なのですけれども、今後、特にここに出てきていない特別支援教室の指導場所や、今後増える不登校の子の、授業に出ないで指導を受けるところなども検討して、学校の施設を整備していく必要があると思うのですけれども、繰り返しになりますけれども、その点だけすみません。"},{"i":103,"speaker":"柏木学務課長","text":"ここに書かれていない、ご存じのように今年度から教育委員会として進めていくものもございますので、そういう教室も含めて、きちんと確保できるように進めてまいります。"},{"i":104,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(2) 令和６年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副園長・副校長異動者名簿について"},{"i":105,"speaker":"つる委員長","text":"次に、(2)令和６年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副園長・副校長異動者名簿についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":106,"speaker":"中谷指導課長","text":"それでは、お手元の資料に基づきまして、令和６年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副園長・副校長の異動状況についてご説明申し上げます。\n裏面をご覧いただければと存じます。まずは資料の見方でございますが、上段から、小学校、中学校、義務教育学校、幼稚園となってございます。左から通し番号がついておりまして、学校名・園名、その隣に校長・園長の枠、そしてその次に副校長・副園長の枠となっております。異動のあった部分につきまして、小学校から順にご説明いたします。\nまず、校長の異動状況でございますけれども、小学校につきましては１２名が異動となっております。上から順に申し上げます。小学校１番、城南小学校の高橋校長が、浅間台小学校からの転任です。２番、浅間台小学校の谷脇校長は、八潮学園からの昇任です。"},{"i":107,"speaker":"つる委員長","text":"もし羅列であれば、書面のとおりでよろしいかと思います。"},{"i":108,"speaker":"中谷指導課長","text":"承知いたしました。では、そのようにさせていただきます。ありがとうございます。\n今、１２名が異動者と申し上げましたが、５名が区外からの転任または昇任となっております。\n次に中学校でございますが、ご覧いただいておりますとおり、５名が異動となっております。そして、この５名のうち２名が区外からの昇任となっております。\n続きまして、義務教育学校でございますが、４名が転任です。４人の区外からの異動者はございません。\nそして、右側の副校長の異動状況でございますが、小学校では９名、中学校では１名、義務教育学校では３名の副校長が異動となっております。\n合計、異動者１３人のうち、５名が区外からの転任または昇任、８名が区内での転任または昇任でございます。\n最後に幼稚園でございますが、１名の園長が異動となっております。ご覧いただいているとおりとなっております。"},{"i":109,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":110,"speaker":"安藤委員","text":"向学のためにと言いますとあれですけれども、こういった管理職の異動先というのは、現行ではどのように決定されているのか、どのようなルールに基づいて誰が決めているのかというあたりを教えてください。"},{"i":111,"speaker":"中谷指導課長","text":"現在ご案内させていただいております異動ですが、全て東京都の教職員ということになっておりまして、根拠としましては、東京都教育委員会の異動要綱となっております。プロセスとしましては、前年度のうちに、主立ったものですけれども、ご本人からお一人お一人の希望先といいますか、これからどうしていきたいのかというところをお伺いしまして、それとともに、最終的には総合的に区教育委員会でも、どういった形がよいかということをまとめさせていただきまして、都の教育委員会に内申という形で申告いたします。最終的には、東京都の教育委員会が私たちにヒアリングを行いまして、東京都教育委員会が決定するというようなプロセスとなってございます。"},{"i":112,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":113,"speaker":"高橋（し）委員","text":"区の独自採用の先生についてお尋ねするのですが、３人の副校長先生がいらっしゃって、これは昨年から続いているのかということで、１つ確認と、それから、この３人の副校長先生が、ほかではなくて、この３つの学校に置かれている理由というか、なぜいらっしゃるかというのと、それからあと、現在、今度、管理職の校長先生になる資格というか、そこまでの先生方がいて、また、もちろん次になっていただきたいという意味を含めてですけれども、そういう状況の先生方も何人かいらっしゃるのかということをお聞きします。"},{"i":114,"speaker":"中谷指導課長","text":"３点ご質問いただきました。\nまず、区の固有教員の副校長の配置状況ですけれども、ご覧いただいている３名の配置につきましては、昨年度から引き続きというところになっておりまして、今回の異動はございません。\nそして、配置理由ですけれども、主には大規模校の支援という観点や、あとは学校として特に教育の特色ある活動を進めていくために必要な人材が求められているという視点で置いているところでございます。\n３番目としまして、次に管理職になり得る人材はいるのかというところですけれども、副校長になるために、今現在、主幹教諭や指導主事といった役職を担っている者が固有教員の中にいます。こういった方々に管理職選考を促していきたいと思っております。"},{"i":115,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n会議の運営上、暫時休憩いたします。\n○午後 ３時０１分休憩\n○午後 ３時１３分再開"},{"i":116,"speaker":"つる委員長","text":"休憩前に引き続き、文教委員会を再開いたします。\n────────────────────────────────────────────\n(3) 令和６年度（７年度採用）品川区立学校教育職員採用候補者選考実施について"},{"i":117,"speaker":"つる委員長","text":"次に、(3)令和６年度（７年度採用）品川区立学校教育職員採用候補者選考実施についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":118,"speaker":"中谷指導課長","text":"それでは、私から、令和６年度（７年度採用）品川区立学校教育職員採用候補者選考の実施につきまして、ご説明させていただきます。資料をご覧ください。\nこちらにつきましては、令和７年４月１日に採用予定の品川区立学校教育職員の採用候補者選考の日程についてのものでございます。\nまず１番、採用予定人数でございますが、６名程度を予定しているところでございます。\n続きまして、２、資格要件でございますが、（１）としまして、小学校教諭普通免許状および中学校教諭普通免許状（教科不問）の両方を所持する者と、（２）としまして、小学校教諭普通免許状および特別支援学校教諭普通免許状の両方を所持する者。この（１）と（２）のいずれかに該当する者とさせていただいております。\n続きまして、３、選考区分でございますが、昭和３８年４月２日以降に出生した者となります。こちらが一般選考、一般区分になります。そして、今回新たに、大学３年生前倒し選考を追加して行いたいと考えております。第一次選考の教職教養のみを前倒しして受験することができる制度になっています。大学３年生等で令和７年度中に卒業見込みで、免許状も取得見込みであり、昭和３９年４月２日以降に出生した者を対象にいたします。\n最後に、４、選考日程でございますが、裏面をご覧いただければと存じます。募集期間は、令和６年４月２４日から６月２８日までを予定してございます。その後、第一次選考は令和６年７月２０日土曜日、結果発表を経まして、第二次選考を令和６年８月３１日土曜日、最終採用面接につきましては令和６年９月２１日土曜日を予定させていただいております。"},{"i":119,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":120,"speaker":"安藤委員","text":"昨年は５名程度採用をかけてということだったのですけれども、この４月に採用できたのは何人だったのでしょうか。今回、６名程度採用ということなのですが、昨年度にやはり退職者が出たのか、あるいは去年、５名の採用ができなかったということなのか。その辺を伺いたいと思います。それと、前倒し選考の目的について伺いたいと思います。"},{"i":121,"speaker":"中谷指導課長","text":"まず、この４月１日に採用できた人数でございますが、２８名となっております。ちょうど１年前に２５名でスタートさせていただきまして、５名を採用させていただいております。そして、先ほど申し上げた、２名が退職というところがございまして、２８名での今回のスタートというところになっております。\nそれから、前倒し選考ですけれども、今、東京都教育委員会でも新規採用教員の募集に関して様々な工夫をしておりまして、幾つかある中でも、品川区といたしましても優秀な方を早くに確保させていただくという観点から、この制度は取り入れてよいのではないかという結論に至りまして、このたび、やらせていただくというものになっております。"},{"i":122,"speaker":"安藤委員","text":"２８名で６名程度ということは、独自教員を増やすという考えなのか、それとも退職者を見込んでということなのでしょうかというところをお伺いするのと、それと、途中退職がどうしても毎年あるのですけれども、独自教員で採用された教員の途中退職者の要因というのはどういうふうに考えているのでしょうか。伺います。"},{"i":123,"speaker":"中谷指導課長","text":"２つ、いただきました。\nまず１つ目ですけれども、今後増やすのかというご質問ですけれども、現在、２８名でスタートいたしまして、例年ですと、３０名を満たすためというところを目標にやってきておりますので、２名というところになるのですが、今後、やはり東京都の教職員の管理職も、一定程度期間が過ぎますと異動というところで、かなり品川区の教育政策をやってきておりますけれども、東京都の教員の入替えというところも考えますと、行く行くは、将来的に各学校にお一人の固有教員がいらっしゃって、品川区の教育施策に関してはこうやって進めるのだという、校長が入れ替わったとしても、しっかりと体制としては推進できるというところをつくっていきたいという思いも込めまして、少しずつ増員させていただくということを、今回の選考から考えております。ですので、今回、プラス４名というところも含めての合計６名程度という形にさせていただきまして、この４名という数も、これまで採用選考をやらせていただく中で、何でもかんでも一気に採ればいいというものではないというところも、ある意味、感触として学ばせていただいているところですので、この辺りの数が妥当であるのではないかと判断しております。\nそれから２つ目のご質問で、途中退職者の方の原因ということなのですけれども、こちらにつきましては、やはり今回はお２人ということでしたけれども、それぞれ、ご家庭の事情であったり転職であったりというところで、ケース・バイ・ケースというところを申し上げさせていただきます。"},{"i":124,"speaker":"安藤委員","text":"ということは、今、小・中学校を合わせると、３７小学校、前期課程があって、それに後期課程がかぶるので９を足すと、４６名を目指すということですねという確認をしたいのと、それと、そうですね。ただ、毎年、退職者が出てしまうというのは品川区だけではないのです。なかなか、やはり学校現場に対しての環境が厳しくなっていて、そういう方が増えているということだと思いますので、ケース・バイ・ケースで終わらせないほうがいいのではないかと思いますので、きちんと続けられる、なるべく途中退職者が出ないような職場環境をつくっていただきたいと思います。\n最後になります。関連して、この４月現在で、いろいろ今、教員の採用自体が厳しい状況になってきていると思うのですけれども、未配置・未充足の教員というのは、品川区の合計でどれぐらいいるのでしょうか。例えば、産休代替を含む担任では何人ぐらい未充足の人がいるのかとか、専科のほうはどうかとか、特別支援の関係の未充足などというのは何人かなど、もし内訳など分かれば、それも併せて教えていただければと思います。"},{"i":125,"speaker":"中谷指導課長","text":"３点、ご質問をいただきました。\nまず、行く行く４６名、４６校ということで、こちらを目指すのかというご質問ですけれども、そのとおりでございます。段階的にやっていきたいと思っております。\nそれから２つ目といたしまして、退職者を出さない工夫というのはやってございます。一番大事なことは、お一人お一人のヒアリングをしっかりしていくというところだと捉えております。これは、固有の教員だけではなく東京都の教員も同じことでございまして、特に新人の方でお入りになった方や、あとは外からの転入で、品川区に入られた方など、環境がご本人にとって大きく変わる方に関しては、しっかりお声を聞いて、どのようなことで今悩んでいるか、どのようなことが逆にうまくいっていて、これからどんなことを目指そうとしているのかといったところをしっかり聞いてまいりたいと思っておりますし、これまでもやってきておりますということをお伝えさせていただきます。\nそれから、未配置の教員ということで、こちらのご質問は東京都の教員のことかとは思っておりますが、こちらにつきましては、今、４月９日の時点で、欠員の状況としましては、正規の欠員の方が、区内の学校を合わせまして５人、そして産休・育休代替の欠員が６名で、合計１１名になっておりましたが、この後、補充が幾つかなされておりまして、現時点では合計で７名という形になってございます。"},{"i":126,"speaker":"つる委員長","text":"よろしいですか。ほかにございますか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(4) 運動部活動の地域移行に係る協議会（第２回・第３回）および文化部活動の地域移行に係る協議会（第２回）の報告について\n(5) 令和６年度品川区地域部活動スケジュールおよび学校部活動の民間委託について"},{"i":127,"speaker":"つる委員長","text":"次に、(4)運動部活動の地域移行に係る協議会（第２回・第３回）および文化部活動の地域移行に係る協議会（第２回）の報告について、および、(5)令和６年度品川区地域部活動スケジュールおよび学校部活動の民間委託についての２件を、関連するものとして一括して議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":128,"speaker":"中谷指導課長","text":"運動部活動の地域移行に係る協議会（第２回・第３回）および文化部活動の地域移行に係る協議会（第２回）、そして、こちらに併せまして、品川区立学校 部活動の在り方に関する方針の改訂につきましてもご報告させていただきたいと思っております。\n資料をご覧ください。区立学校の部活動の地域移行のあり方等を総合的に検討することを目的といたしまして、校長、ＰＴＡ代表、地域代表、区内のスポーツ選手や文化振興の関係者を委員として構成しまして、令和５年１２月１２日に運動部の協議会第２回、そして令和６年２月２９日に運動部の協議会第３回と文化部の協議会第２回を合同で開催しております。\n１ページ目をご覧いただければと存じます。まず、運動部の協議会（第２回）についてです。昨年度より、子どもたちに、多様なスポーツに取り組める機会をつくるため、民間の団体や企業への委託を進めている地域部活動、ラグビー、ホッケー、バドミントン、ダンスのそれぞれの進捗状況について、事務局よりご報告いたしました。\n裏面をご覧ください。運動部の協議会（第３回）と文化部の協議会（第２回）となっております。こちらの会では、先ほど申し上げました「品川区立学校 部活動の在り方に関する方針」の改訂の方向性について協議をいたしまして、内容についてご了承いただきました。それぞれの会で委員の方々からいただいた主な意見を記載させていただいてございます。\n２枚目以降についてですが、それぞれの地域部活動の進捗状況についての参考資料となっております。それぞれの種目につきまして、総括の部分を中心にご説明させていただければと思います。\nまず、ラグビーの総括につきまして、６ページの下段をご覧ください。運営につきましては、教育委員会との連携において、学校の朝会であったり様々な場面で、社会人チームのラグビー選手の方を招いての募集・周知をおこなったことで、第５学年から第９学年まで幅広い申込みがございました。一方で、運営面については、体制の強化に向けて工夫が必要であると感じております。\n続きまして、ホッケー部の総括になります。１０ページをご覧いただければと存じます。運営に関しましては、スポーツ推進課等と連携して、情報提供、学校への周知を行うとともに、八潮地域の関係の会場を確保して実施いたしました。委託先の東京都ホッケー協会は、元日本代表の経験を持つオリンピアンや、日本ホッケー協会、アスリート協会委員長など、多彩な経験をお持ちの指導者が来てくださいました。さらに、オリンピックスタジアムで複数の私立中学校との交流試合もすることができまして、充実した活動となっております。次年度につきましては、部員数の確保を課題と捉えて、事前に体験会を行うなど、案内をさらに徹底していきたいと思っております。\n続きまして、１４ページをご覧ください。バドミントン部の総括となっております。運営につきましては、１か月前の周知や説明会の開催によって、第５学年から第８学年まで定員を超える申込みがございました。課題としては、派遣された指導者がお一人ということで、経験差のある異学年集団を指導することについて、難しい場面があったことです。そこで、指導課の担当がフォローを行うなどしまして、課題解決を図りました。結果としましては、参加された方にとって大変充実した活動内容となっております。\n最後に、ダンス部についてでございます。１５ページになります。こちらは、協議会を開催した２月２９日の時点で活動中でございましたので、中間報告の形となっております。\n大変失礼しました。ページ数がきちんと振られておりませんで、申し訳ございません。４つ目の種目のところにダンス部とございます。そちらをご覧いただければと存じます。\nまず、タイトルのところに「ダンス部（継続中）」となっている資料がございます。こちらを基にご説明をさせていただきたいと思います。\nこちらが、現時点で中間報告という形になっています。委託先につきましては、地元企業のセガサミーホールディングスの株式会社のグループ会社である株式会社ウェーブマスターとなっています。全５回、２月４日から３月３日までの日曜日、活動時間は１３時３０分から１５時３０分、練習会場は品川区立五反田文化センターのスタジオで行いました。部員数につきましては、募集時、３０名としておりましたが、多数のご応募をいただきましたので、会場の広さを考慮して５名追加いたしまして、参加人数を３５名としております。指導者は、プロダンスリーグのＤリーグに参戦しているプロダンスチームの選手です。ヒップホップダンスを経験し、楽しく踊ることを目的としながら充実した活動となりました。\n続きまして、資料を飛ばせていただくのですけれども、「品川区立学校 運動部活動の在り方に関する方針」の改訂につきまして、Ａ４判で横になっております資料をご覧いただければと存じます。今回の改訂に当たりましては、資料の中段の中の「内容」にお示しさせていただいたとおり、「スポーツ・文化芸術環境を構築する観点に立って、児童・生徒のニーズを踏まえ、部活動が多様な形で最適に実施されることを目指すこと」、「部活動の指導・運営にかかる体制を構築する際、学校全体として教職員の負担軽減を図る趣旨を踏まえること」等を明記する予定です。内容の詳細につきましては、その下の囲みに記載させていただいております。\nなお、参考といたしまして、その後のページに現在の方針をお付けしております。こちらの内容をベースに改訂を行わせていただきまして、４月中には各学校へ改訂を配布予定としております。\n続きまして、令和６年度の品川区地域部活動スケジュールおよび学校部活動の民間委託についてご説明を差し上げます。Ａ３横判の資料をご覧いただければと思います。\nまず、部活動を地域移行する意義につきましては、昨年と同様に４点ございます。「持続可能な取組とし、地域で子どもたちの育成に寄与していくことができるようにする」こと。「スポーツや文化芸術の楽しさや喜びを感じるとともに、自己実現や地域への愛情を持てる人材を輩出できるようする」こと。「学校の教育の質を向上できるようにする」こと。そして４点目としまして、「区民がスポーツや文化芸術の価値を享受できるようにする」ことです。\n実態につきましては、令和５年度の教育委員会、文教委員会でお示しさせていただいたものとなっております。課題の主立ったものとしましては、生徒等の地域における活動機会の確保、地域における適任指導者の確保、義務教育終了以降、区内で区民として参加できる活動との連携、学校の働き方改革の推進および教職員の兼業・兼職の体制整備などがございます。\n次に、課題に対する取組についてです。地域部活動については、令和５年度に開始いたしました、ホッケー部、ラグビー部、ダンス部を継続して行い、資料の中段右にお示ししましたとおり、児童・生徒や保護者からの希望もございまして、各部活動の活動の回数や募集人数を増やすことで、多様な運動機会の創出を図ってまいります。\n学校部活動につきましては、令和６年度は、各学校の部活動に、まず部活動指導員の拡充をしてまいります。そして、新規事業としましては、学校と部活動指導員および地域スポーツクラブ、文化団体等との連絡・調整等を行う学校部活動アシスタントコーディネーターの配置を計画しております。さらに、学校の働き方改革の推進に向けて、地域の指導者がいない学校部活動を１校当たり２部活程度、民間に業務委託をしてまいります。全体的に地域の指導者が増えていくというイメージになりますが、一部は継続して教員が顧問を行ってまいります。\n資料下段につきましては、令和６年度の全体のスケジュールとなっております。協議会の定期的な開催を通じまして、新規事業も含めて、今年度も実証事業の効果を検証してまいります。\n最後になりますが、別にございますＡ４の資料をご覧ください。こちらにつきましては、令和６年度の部活動に関する取組をお知らせするために、対象となる５学年以上の児童・生徒や、区内の全学年の保護者にお配りしているものとなっております。表面は主に地域部活動に関するもので、裏面は、４月５日時点で各学校の民間委託を行う部活動を一覧にしたものとなっております。\nどうぞよろしくお願いいたします。"},{"i":129,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":130,"speaker":"安藤委員","text":"まず、すみません。部活動の在り方に関する方針の改訂なのですが、資料で説明されたのですが、少しまだ理解できていないところがあるのです。どこが改訂されたのかというのは、もう一度、改めて教えていただきたいというのが１点でございます。\nそれと、最後のチラシの裏の「学校部活動の一部民間委託」というところなのですけれども、これは先ほどの説明ですと、指導者がいないというところを委託していますということでしたので、現在、その中学校にはない部活を委託しているということの理解でよろしいのでしょうか。伺いたいと思います。"},{"i":131,"speaker":"中谷指導課長","text":"２点、いただきました。\nまず、部活動の在り方に関する方針の改訂でございますが、Ａ４の横判のほうをご覧いただいているかと存じますが、主に丸ポチで示させていただいた、２つございます。１つは、スポーツ・文化芸術環境の整備ということで、子どもたちにとって、より運動の機会であったり、文化芸術に触れることができる機会を増やしていこう、促進していこうというところでの改訂でございます。これに沿って、品川区教育委員会で行わせていただいているものとして、先ほどご案内させていただいた、ラグビーやホッケー、そしてダンスの取組ということがございます。\nそれからもう一つにつきましては、教職員の負担軽減を図る体制構築ということでございます。こちらは、今、こういった改革推進期間になっている背景として出てきているものなのですけれども、やはり地域の方々との連携の下に、これから教員だけが部活動の運営を担うのではなく、連携しながら取り組んでいくことの必要性というものが書かれております。こちらにつきましても、今回、学校の部活動の民間委託をさせていただく取組や、部活動のコーディネーターの配置、また部活動指導員の拡充なども含めて、こういった取組とリンクさせながら、お示しさせていただきたいと思っております。\n２つ目のご質問としましては、民間委託についての中で、地域の指導者がいないというところで、どういった部活に対して今回の民間委託をしているのかという趣旨のご質問だったかと思いますが、学校によって、例えば今、現存しない部活動を新たに立ち上げて、そこに民間委託をなさるということを決めた学校もございますし、または、現在ある、これまでは教員が顧問になっていた部活動に対して、これからは地域の指導者が入ることにしようということで取り入れたという学校もございます。つまり、どのようにして対象となる部活動を決めたかという経緯につきましては、各学校の現状を見据える中で、最終的には校長先生がご判断をされて、こちらにお申出をされたところを調整させていただいているものになります。"},{"i":132,"speaker":"安藤委員","text":"そうですね。各学校当たり２つということなのですけれども、そうなると、３０ぐらいの部活が委託されると思うのですけれども、委託先の株式会社リーフラスというところがありますが、こちらに委託した理由と選考方法などを伺いたいのと、あと、これだけの部活業務というのを受けられるのでしょうかという、すごい不安があるのですけれども、その辺はどうなのでしょうかということも伺います。\nあと、Ａ３横の資料でお伺いしていきたいのですが、改めてアンケートを見直してみますと、部活動は子どもたちの成長の場になっている、あるいは、活動機会や費用面の負担などの懸念などもありますし、生徒会長からも、費用負担が増えないようにしてほしいということも出されております。何よりも、現在の部活動に肯定的なのは９２％ということで、やはり、これまでいろいろ、時代に応じて改善しなくてはいけない点はあったにせよ、本当に子どもたちの大事な貴重な成長の場になっていたと思うのです。それが、今まで学校での教師が身を犠牲にして続けてきたというようなことを、時代に応じて変えていかなくてはいけないというのが大きな背景になって、こういうものを決めているとは思うのですが、これは改めて区教育委員会としては、学校活動のどの役割というのを地域に移行しようとしているのかというのについても、もう少し伺えたらと。様々、これまで担ってきた大事な点があると思うので、そこについて伺いたいと思います。"},{"i":133,"speaker":"中谷指導課長","text":"まず民間委託のものにつきまして、リーフラスに決めた選考方法としましては、プロポーザルで行っているところでございます。規模としましては３０、つまり２部活程度掛ける１５校ということで、３０部活動というところを１つの目安として契約しているものとなっております。ただし、一概に２部活動と申しましても、選んだ部活動によっては、かなり日々、頻繁にやる部活動もあれば、もしくは極端に申し上げますと週１回程度行う部活動というものもありますので、その辺りの活動量というところを、最終的には業者と調整しながら、学校の希望を最大限に聞いていく形で調整してございます。\n今ご覧いただいているのは、４月５日時点というところで、やや古いものになっておるのですが、現在、また数部活程度、学校からお申込みがありまして、業者と調整いたしまして、受け入れることができるということで、今、３４部活動を、トータルとしては委託していこうということで進めさせていただいております。\nそれから、活動負担の懸念というところで、お子様からのご意見をいただいているところですけれども、こういった声というのは大変貴重な情報なので、これからも声を聞くというところは、今年もやっていきたいと思っているところです。早速に、費用面というところでは、やはり部活動をやる中でも一番のよいところというと、やりたいと思ったときに参加しやすくて、そこに費用面でのハードルができるだけないということが大事なところだと、お子さんの声も聞いた中で捉えておりますので、そういったところにおいては、できるだけ費用負担がないような形で進めることができればというところで、今現在、検討しているところでございます。\nそれから最後のご質問で、教員から今後、地域の方々へ移行していくことによって、地域の方にどういった役割を担ってほしいのかというご質問であったかと思います。こちらにつきましては、まずは今回、民間委託の内容を決めていくに当たりまして、昨年度の実証事業であるラグビーやホッケー、バドミントン、ダンスの成果と課題をしっかり見据えて委託内容を決めさせていただきました。というのも、指導に関してたけている方が集まってくださることは大変よいことだと感じさせていただいている一方で、運営面で、やはり部活動の運営というのは大変細やかにやらなければいけないことがあり、それを今までは教員が全て担っていたわけですけれども、例えば欠席者のご連絡。実際、活動時間になってもいらっしゃらないお子さんに対してご家庭にご連絡をしていくといったことは、活動が始まった直後に、教員の顧問はすぐに連絡するということを、当たり前のようにやるわけなのですけれども、そういったことを含めて、細かいですけれども、しっかり滞りなく、連絡し忘れてしまったということがないようにやっていくような運営体制というのも、民間の企業としっかり連携させていただく中においては約束して、しっかり進めていきたいと思っているところです。\n今、例えばというところで申し上げたのですけれども、こういった運営面での細々とした、やっていただきたいということを盛り込ませていただきながら、まず令和６年度、学校部活動への民間委託ということで進んでまいりたいと思っております。"},{"i":134,"speaker":"安藤委員","text":"そうですね。今の答弁も理由になっていたかもしれないですけれども、プロポーザルで募集したというのは分かるのですけれども、そこを選考した理由というか、プロポーザルの、区の考え方というのですか、理由について、ここを重視したというのがあれば改めてお伺いしたいのが１つ。\nもう一つ、Ａ３の一番上の意義の４つのところを書いていますけれども、これに関連して伺いたいのですが、「持続可能な」というところがありますけれども、これは大変、基本的に重要なのですが、これは、持続可能な取組にするためには何が鍵だとお考えなのか伺いたいというのが１つ。\nそれと、３つ目と４つ目に、「働き方改革の推進」というのもあると書いています。さらに下には、「部活動といった一定期間の活動期間にとどまらず、継続的に確保することで、区民がスポーツや文化芸術の価値を享受できるようにする」と書いているのですけれども、率直に、この意義というのがかなり欲張りというか、なかなか大変な意義だと思ったのですけれども、最終的に、将来的に、地域移行の目標というのは、区教育委員会としては、ここまでやるのだという目標などはあるのかどうか、そちらをお伺いさせてください。"},{"i":135,"speaker":"中谷指導課長","text":"まず３点、いただきまして、プロポーザルのことですけれども、重視したことが少し重複するところもあるかと思うのですが、やはり指導の、競技や種目の専門性だけではなくて、運営面で、いかにきめ細かく提供してくださるかというところを、同じぐらいの重きを持って見させていただいたということがございます。\nそれから、Ａ３判のほうで、意義についてのご質問なのですけれども、持続可能な活動とするために何が鍵かというところですけれども、やはり一番は、これまで教員が担ってやってきたことを地域の方々に移行させていただくという一連のプロセスの中で、子どもたちに混乱を与えないように取組を提供していくというところかと思っております。例えば今、学校で、どの部活動は民間に委託しようということを決めてやっていくわけですけれども、ある日突然、先生がいなくなって、突然知らない方が入ってきても、大変混乱します。保護者の方もお子様も同じ思いになるかと思っています。そういった中で、委託はするのですけれども、やはり今までのやり方、それは恐らくそれぞれの部活ごとに、いろいろな方針があって、やり方もあり、そういったところをしっかり引き継ぎながら、思いを酌んで、地域移行につなげていくというところにおいては、打合せを非常に大事にしております。ちょうど、本日で１５校全てのヒアリングが終了するのですけれども、全ての各学校の各部活動の特色や、引き継いでいきたいところというのを、指導主事の立会いの下で、学校の先生方と業者の方とを併せて丁寧に聞き取るというような取組を今させていただいております。この後に、全体の教員への説明会や保護者の方への説明会といったものを今予定してございますが、そういったところも、お子さんだけでなく周りの大人も共通理解に立って移行ができるように進めていきたいと思っております。\nそして、最後のご質問ですけれども、最終的な区教育委員会としての目標はどのようなものかというところで、今、非常にいろいろなことを試行しながらやっているという段階だと認識しております。令和７年度までが改革推進期間となっておりまして、令和７年度末までに、一定の学校の部活動の民間委託については、希望されて顧問をなさる方を除いての部活動については、何らかの形で地域の部活動指導員の方や民間委託の方々など、地域の方に担っていただくという体制をつくっていきたいと思っております。また一方で、地域の部活動につきましても、３種目、ホッケーとラグビーとダンスにつきまして、これを同じような形態で進めていくのか、もしくは拡大していくのか、特にご意見としていただいているのは、シーズンスポーツではなくて通年でできないだろうかと。これは、非常にうまくいっているから、もっとやってほしいというような好意的なご意見をいただいているのかと思っておりますので、こういったところも、令和８年度以降に、できるかどうかというところも含めて検討しながら実行できるようにしていきたいと思っております。最終的には、品川区のお子さんたちが、自分が好きなことに熱中することができて、それが、卒業してからも自分からやってみたいと思ってくれるような、そういう活動になっていけばいいというのが願いでございます。"},{"i":136,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":137,"speaker":"高橋（伸）委員","text":"すみません。幾つか質問させていただきます。\n協議会の報告についての７ページ、児童・生徒アンケートです。ホッケー部に関しては、部員数が５名だった。指導者数が６名で、指導者の方のほうが多かった。その中の総括のところで、部員募集について期間が短かった。今後この周知をもっと幅広くやっていくということなのですけれども、これも具体的にどういう手法でやって募るのかというのを教えていただきたいのと、あと１１ページのバドミントン部です。これも、１２ページを見ると、4)の地域部活動を通してどのようなことを得られましたかというと、ほかの部活動との違いが、技術向上がすごく特化しているのと、運動の楽しさ、物すごく横棒が伸びている。これは、独自の何かバドミントンの楽しさというのが、すごく、本来の部活動とはまた違う楽しさが、垣間見えたのかと私なりに思ったのですけれども、そこの分析はどういうふうになっているのだろうということです。あと、１５ページのダンス部です。当初、これは募集３０名だったのですけれども、広さも考慮して５名追加と書いてありますけれども、これも、Ａ４判のカラー刷りのところを見ると、今年度は、ダンス部とラグビー部とホッケー部があって、３コマあります。それで、ダンス部で、当初、これは五反田文化センターだったのが、今度、御殿山小学校が活動場所になったという記載があるのですけれども、これもどのぐらい、３０名程度と考えているのか、あるいはもう少し、４０名など考えておられるのか、お分かりになる範囲で教えていただきたいと思います。"},{"i":138,"speaker":"中谷指導課長","text":"３点、ご質問をいただきました。\nまずホッケーについてですけれども、今回、部員の募集期間が短く、そして結果として部員が５名だったというところを踏まえまして、今回、部員の募集を拡大していきたいと思っております。まずは少なくとも１か月前からは募集を開始するということに加えまして、並行して体験会を新たに４回やりたいと思っております。これは、部員として入るかどうかを決める前の入部体験会というようなものです。そして、その中で決めていただくというところをやっていきたいと思っております。今回入ってくださった５名の方々が非常に満足度を高く持ってくださっているというところも強みにしていきたいと思っているので、お友達からお友達へというような横のつながりも広がっていければいいと期待しております。\nそれから、続きましてバドミントンですけれども、今回、技術や運動の楽しさ、非常によかったというお声もいただくことができました。こちらの運営としましては、学校の部活動と一番違うところとしては、学年差の大きい方、異学年の方々が集合している。そして、なおかつ、そこに初心者の方もいらっしゃれば、かなり大会で、都大会など大きな大会に進んでおられるような方もいらっしゃるというところで、どのような練習風景であったかというと、かなり熟達されているお子さんが、初心者の方に教えてくださる。指導者が１名だったということもありまして、非常に助け合うというか、子どもたち同士で、かなりケアしながら活動に参加するというようなところが見られたことが特徴的だったと思っております。\nそれから、最後にダンスについてですけれども、非常に応募人数が多くなると見込まれておりますので、昨年度の五反田文化センターですと３５名までが、安全面も考慮した中での最大人数になってしまうので、会場を変更させていただきまして、御殿山小学校とさせていただいております。こちらにつきましては、恐らく今回応募いただいた、７６名いらっしゃったのですけれども、その方々も含めた８０名ぐらいを、活動場所として入ることができるという見込みを立てさせていただいておりますので、もちろん、多くなってしまえば抽せんということも１つの視野には入れておりますが、できるだけ、希望する方々に参加していただく環境という意味で、活動場所を変更させていただいたという経緯でございます。"},{"i":139,"speaker":"高橋（伸）委員","text":"本当にダンスは人気だと思いますので、できるだけ皆様の活動場所を多く取り入れていただきたいと思っております。\nあと、ホッケーに関しては、ホッケーも本当に周知をやっていただいて、本当に大井ホッケー競技場はなかなか、オリンピックでできた、ああいうところでできるのはすごい体験。活動の場としてはすごいと思うので、ぜひ、それも併せてよろしくお願いします。\nあと、最後になるのですけれども、「地域部活動について」の裏面の「学校部活動の一部民間委託」です。これは、吹奏楽部が、浜川中学校と荏原第五中学校と品川学園。吹奏楽部が３校あるのですけれども、これは、業務内容はそれぞれいろいろ、連絡・対応、引率などありますけれども、これも当然、指導も含まれるということですか。それを確認だけさせていただきたいと思います。"},{"i":140,"speaker":"中谷指導課長","text":"吹奏楽部につきましても、もちろん指導も含めて担っていただくということでやっております。"},{"i":141,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":142,"speaker":"ゆきた委員","text":"今、高橋伸明委員から話があったところに関連して、昨年度、ラクビー、ホッケー募集に対しての人数が少なかったということで、その対策として、ただいま答弁がありましたとおり、体験会を取り入れて行うということでしたが、体験会の周知の仕方と、あと金額の設定などどのようにしていくのか、お聞きできればと思います。"},{"i":143,"speaker":"中谷指導課長","text":"体験会につきましては、まず昨年と同様にはなるのですけれども、チラシに、今までやっておりましたオンラインでの説明会ということと加えて体験会を行いますというようなことも盛り込ませていただいて、オンラインの説明会でも、また繰り返しご案内をしていくというような形を取らせていただいています。\n金額の設定については、昨年は取っておったのですけれども、今回は設定はしておりませんというところをお伝えさせていただきます。"},{"i":144,"speaker":"ゆきた委員","text":"昨年度からのアンケートで、体験した結果からは好評価の声が多いので、一度体験させていただくことが関心を高めることにつながる取組だと感じています。地域部活動は現在、実証事業で模索しながら進めているところだと思われますが、交通手段の課題、あと期間の延長など、分かる範囲で今後のさらなる展開をお聞きいただければと思いますが、よろしくお願いします。"},{"i":145,"speaker":"中谷指導課長","text":"令和５年度の活動が１つの競技に対して幾つかの会場を取らせていただいたのが、いろいろな趣旨を持ってやっておったのですけれども、お子さんからのアンケートでは、やはり結構いろいろなところに行くことが大変で、分からなかったら不安だというようなこともあったので、そこは反省点と捉えまして、次年度については、お示しさせていただいたとおりですけれども、かなり会場を絞った形でやらせていただきたいと思っております。これによって少し、保護者の方も含めて、不安感が解消できることにつなげられたらと思っています。併せて、やはり会場がしっかり取れるということも、我々スタッフサイドのことなのですけれども大事なところなので、そこがやはり課題としてはあるところなので、そこも早めにやっていきたいと思っております。"},{"i":146,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":147,"speaker":"高橋（し）委員","text":"最初に、すみません。地域の部活動と学校の部活動の、Ａ３の小さいほうが、児童や生徒に配られるのですか。まず最初の周知のことをお伺いいたします。"},{"i":148,"speaker":"中谷指導課長","text":"お子さんと保護者の方にお配りさせていただいているものが、Ａ４の裏表のものになってございます。"},{"i":149,"speaker":"高橋（し）委員","text":"それで、もう少し詳しいものをまたお知らせしますと書いてあるのですけれども、そのときに、先ほどの総括のところでいろいろ見させていただいたら、そこに、練習日記や感想などで、非常に楽しかったとか、役に立ったということがたくさん書いてあったのです。だから、こちらはＱＲコードで応募が出ているのですけれども、ＱＲコードで、各部活、ダンス部やラグビー部が、どういうふうに参加した人たちが楽しんだかというのが分かるようにまとめれば、余計、入りたいというふうになるのではないか。説明会に行かなくても、まずはそれはできるのではないかと思うので、この紙のほかに何か、配るときに、もしできればそういうものをやっていただければ、よろしいのではないかと思います。まず、それが１つ教えて下さい。"},{"i":150,"speaker":"中谷指導課長","text":"ご指摘いただいたとおり、１つのチャンネルだけではなくて、幾つかの方法で情報をキャッチできるようなところを検討していきたいと思っています。ありがとうございます。"},{"i":151,"speaker":"高橋（し）委員","text":"感想のところに、楽しかった、すごく上手になったなど、たくさん出ているので、それをピックアップして、ＰＲではないですけれども、できると思いますので、ぜひ検討してください。\nもう一つは、学校部活動のほうですけれども、先ほどから課長がおっしゃっているように、非常に打合せをたくさんして、きめ細かくやるというのは本当に重要なことで、そのような姿勢でやられていることはとてもいいと思うのです。先ほどあった、欠席の話などがありますけれども、実はもっと細かいことがあって、例えば、「今日はバスケットボール部が練習だったんだけど中止になったよ。じゃあ、バレー部をやっていいね」みたいなのは、学校の先生方が顧問だったらすぐにできるのです。だから、その辺の調整というか、それは学校側の窓口としては、どなたがスピーディーにできるのかということが１つ。\nそれからもう一つは、学校の教員の先生方で、こちらの部活に関係していない先生方が、あの部活は外部の人がやっているのだからみたいな、そこでの断層というか、それがあると、外の方が指導しているだけに、学校全体として、その部活を動かしていくということに、なかなかつながらないので、そういった先生方の意識の変革というか、それも、同僚がやっていれば、多少のことがあっても、うまく、いろいろやっていけるけれども、そこのところについてどう考えていらっしゃるのかということと、あと、先ほどの外の窓口の、学校のほうではコーディネーターの方になるのですか。すみません。そこもお願いします。"},{"i":152,"speaker":"中谷指導課長","text":"各学校に、業者で総括されるマネージャーのような方がいらっしゃいまして、複数の部活動を見て、今お話をいただいたような、お子さんが、こういう声が上がっているといったところも含めて吸い上げてくださる方が、まず業者にはおりますというところと、あと、それぞれの学校でどういった方が業者との窓口になるかというところにおいては、今現在、打合せしている中で、それぞれ恐らく異なると思います。ある学校では副校長先生になるかもしれませんし、ある学校は校長先生かもしれませんし、ある学校は教員かもしれないしというところで、そこを含めて、今、打合せの中で決めているという段階でございますので、それぞれの学校で、やりやすい方法でコミュニケーションを取っていくというようなところを目指していきたいと思っております。"},{"i":153,"speaker":"高橋（し）委員","text":"すみません。今ので、そこでやはり副校長先生がとなると、副校長先生のお仕事を減らそうと、かなりやっているのですけれども、やはり副校長先生だといって窓口になるおそれと言うとおかしいですけれども、一番いろいろなことが分かっているから、やっていただくのはいいのですけれども、そこのところは学校側でうまく、どなたがやるかなど、協力して体制をつくっていただければいいのではないかと思いました。その辺はいかがですか。"},{"i":154,"speaker":"中谷指導課長","text":"学校でよくあるのは、共有するときに、口頭でやるにしてみても、そこに膨大な時間を費やしてしまって、それが別に、１人の先生だけの問題ではないので、どなたか別の方にお話ししようとすると、また時間がかかってしまうというようなことが一般的にあるのですけれども、そういったことになってしまうと、軽減どころか負担増になってしまうので、例えばそれが、電子の方法で、皆さんに見ていただけることで共有できるとか、そういった方法論の話になってしまうのですけれども、そういったことも含めて検討しながらやっていきたいと思っております。"},{"i":155,"speaker":"高橋（し）委員","text":"すみません。最後にします。\n本当に、今後目指すものでいいことで、１年目なので、いろいろな課題が出てくると思いますけれども、うまくいってほしいという願いを込めてお尋ねしているところと、やはり学校で、部活というのは教員の指導の一つという認識があるのです。そことの兼ね合いを、学校のいわゆる文化というのでしょうか、そこの中でうまく、この仕組みを融合していければいいと思ったのでお尋ねしました。\n最後に１個だけ。継続性なのですけれども、来年はもう、これはやらないとありましたけれども、そういうことについては早めに言えたり、「来年はもう指導者の方が来られないからバスケはないよ」とか、例えばそういうことが、いつ頃分かるのかというのと、そういうものはしっかりと次に向けて、きちんと継続性を持っていけるのか。続けていただくのが一番なのですけれども、そこのところだけ、最後にすみません。"},{"i":156,"speaker":"中谷指導課長","text":"今回、学校部活動の民間委託は令和６年度からスタートしたというところなので、今はかなり慎重に打合せをしてと、やっておりますけれども、軌道に乗ってきましたら、通常の学校の教員がやっているのと同じように、次年度に向けてどういう体制で、どういう指導者になっていくのかといったところは、早めに算段がつくと思っておりますので、令和７年度の開始に当たっては、令和６年度中にしっかり策が取れるようにしてまいりたいと思っております。"},{"i":157,"speaker":"高橋（し）委員","text":"そこで継続性を保っていただきたいという願いです。"},{"i":158,"speaker":"中谷指導課長","text":"おっしゃっていただいたとおり、私たちも継続していきたいと思っておりますので、何とかこの事業が成功するように、全面的に支援していきたい、頑張ってやっていきたいと思っております。"},{"i":159,"speaker":"つる委員長","text":"ほかに。"},{"i":160,"speaker":"せお委員","text":"私からは１点だけ。\n部活動の在り方に関する方針の、ページ数がないのであれですが、４番「児童・生徒のニーズを踏まえた環境の整備」の（１）のところに、略してしまうと、運動部活動も文化部活動も、性別や障害の有無を問わず、多様な潜在的なニーズに必ずしも応えられていないと書かれていて、こういったところを今、ここは改訂されていないと思うので、今現状、どういった状況。障害があるというか、配慮が必要なお子さんなど、そういったお子さんへの、今現状、部活動に関してはどうなっているのかというところと、あと、その下の部分に、多様なレベルや多様なニーズに応じた活動を行うことができる部を設置するとあるので、ここも現状をお聞かせいただきたいと思います。"},{"i":161,"speaker":"丸谷教育総合支援センター長","text":"まず、障害のあるお子さんへの支援ということですけれども、中学校・義務教育学校では、例えば知的障害のある特別支援学級に通っている生徒も、部活動には通常どおり、ほかの通常学級のお子さんと一緒に活動に参加しておりますという現状がございます。また、多様なレベル・ニーズというところですけれども、例えば先ほどバドミントン部の話で、指導者１人でというところがありましたけれども、通常の中学校だと先輩・後輩がいて、レベル別に分けて活動を、初心者の方と、それなりにうまい子と、ある程度、クラスというか、レベル別にグループに分けて指導するといったような活動は行っていますので、そういったことも今後も大事にしながら進めていくことが必要かと考えております。"},{"i":162,"speaker":"せお委員","text":"現状を理解しました。参加できているということで、とてもうれしく思います。\nそれで、部活動の地域移行というところなのですけれども、今現在、学校内で行っていれば、学校の先生方は、そのお子さんお子さんの特性が分かったり、対応の仕方などが分かったりすると思うのですけれども、民間の方たちというのは必ずしもというところがあると思うので、すぐに対応してということではないのですけれども、今後のそういったところの考え方というのはどのような感じなのか教えてください。"},{"i":163,"speaker":"中谷指導課長","text":"今お話しいただいたようなところが、やはり学校としても非常に気になっているところだというのは、打合せの中で共有させていただいておりまして、こういったところも、お子さんの情報の共有の仕方であったり、どうやって支援していくのかというところの手立てを打ったりというところを、少ない部活動数で、まず民間委託を取り入れながら、仕組みづくりといいますか、その学校の中でどういうふうにお子さんの支援を機能させていくかというようなことを検証していくというか、一つずつ、そこをまずやってみようというところで、今スタートしたというところだと認識しているので、非常に成果のある仕組みづくりができたものについては校長会などでも共有させていただきながら、いい仕組みづくりが増えていくような形でやっていきたいと思っております。"},{"i":164,"speaker":"せお委員","text":"まだまだスタートなので、今ご答弁にもあったように、ぜひ好事例を共有していただいて、より多くのお子さんが、ニーズに応じた活動ができるように、私も応援していきたいので、よろしくお願いいたします。以上です。"},{"i":165,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":166,"speaker":"吉田副委員長","text":"今、それぞれ皆さんの質疑の中で、いろいろなことが分かってきたのですけれども、一方で、これは結局、学校部活動指導業務委託という形ですよね。業務委託契約になると思うのですけれども、契約は、いろいろな社判や登録番号などがあるのは承知しているので、どうしても情報開示の手続を取らなくてはいけないのかと思いつつ、その仕様書の中身に、今いろいろ質疑があった内容が反映されているのではないかと思うのです。それで、プロポーザルとおっしゃったので、プロポーザルであれば、先に条件を提示して、提案を受けて、その中から選定していくという形を取られたと思うのですけれども、そういう手続というのは、やはり、ごめんなさい。プロポーザルの情報を見落としておりまして、その条件を見ていないのですけれども、ざっとどのような感じで。それで、契約金額の算定も、プロポーザルだから基本、大体これぐらいの契約金額で、これぐらいの業務をしてほしいという条件を先に出すのかと思うのですが、その中で、その内容であればこれぐらいの事業ができますというような提案というのがされているのだと思うのですが、その辺のことの中で、今までご説明があったことが決まっていくのでしょうか。できたら業務委託契約の仕様書の中身を確認したいのですけれども、それは情報提供という形では頂けないのでしょうか。開示請求が必要でしょうか。伺います。"},{"i":167,"speaker":"中谷指導課長","text":"プロポーザルをやっていく中での、最初に提示した条件というところに関しましては、先ほどいろいろご質問を頂いた中にもちろん反映されているので、例えば部活動の規模や指導者の数、あと統括指導者を置いてくださいということ、あとは、当たり前ですけれども、一番大事なところですけれども、品川区の部活動の在り方に関する方針にしっかり基づいてくださいということや、指導者に対して事前にきちんと研修をしてほしいといった約束事を入れさせていただいているところです。より、今回の学校部活動の民間委託の仕様書については、昨年度の地域部活動の成果と課題を踏まえて盛り込ませていただいているという、先ほど申し上げたとおりになります。\n仕様書が見られるかどうかというところは、今の時点では分からないので、また確認させていただければと思っております。"},{"i":168,"speaker":"吉田副委員長","text":"Ａ３の図によれば６月からということになっているので、それまでにそういう契約などが成立するのかと。その辺のことも、もし何か、いつからいつですみたいな。それで、一応これは３月までになっているので、その期間が契約期間になるのかと。先ほど高橋しんじ委員からもありましたけれども、継続ということになれば、これが更新されていくという形になるのかと。それで、私のあれでは、更新のたびに、何か中身についても修正がされていくのかと思うのですけれども、そういうことを伺いたいのと、品川区側の契約主体は教育委員会ということですか。その辺ももう一回、確認させてください。"},{"i":169,"speaker":"中谷指導課長","text":"実際、学校で指導者の方がお子さんと直接対面してやっていくのは６月頃になると、今、一応出させていただいているのですけれども、移行期間としては、もう始まっておりまして、４月１日から３月３１日までということでやらせていただいております。\n主体に関しては、品川区教育委員会が委託してということでやらせていただいております。"},{"i":170,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(6) 区立学校におけるいじめの重大事態の発生状況について"},{"i":171,"speaker":"つる委員長","text":"次に、(6)区立学校におけるいじめの重大事態の発生状況についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":172,"speaker":"丸谷教育総合支援センター長","text":"それでは、区立学校におけるいじめの重大事態の発生状況について説明いたします。資料をご用意ください。\n令和６年２月に、新規で２件のいじめの重大事態が発生いたしましたので、報告いたします。\n事案番号１１番につきましては、いじめの態様の分類は、冷やかしやからかい、悪口や脅し文句、嫌なことを言われる。重大事態の分類は、１号、身体に重大な被害が生じた疑いがあるもの、および２号、いわゆるいじめにより不登校になったケースで、義務教育学校での事案となります。\n事案番号１２につきましては、いじめの態様の分類は、冷やかしやからかい、悪口や脅し文句、嫌なことを言われる、金品をたかられる等で、重大事態の分類は、１号、身体に重大な被害が生じた疑いがあるものとしております。小学校の事案となります。\nいずれの事案も、現在調査中となっております。\n令和５年度のいじめの重大事態発生は、今回の２件を含め、合計で１２件でございました。順次、調査を進めておりまして、６件につきましては現在、調査が終了しております。それぞれ、ご家庭に公表の可否等を確認しておりまして、公表が可能となったところで議会にも報告させていただきます。\n資料の裏面には、いじめの態様や法律や条例につきまして、参考として掲載しております。"},{"i":173,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたらご発言願います。"},{"i":174,"speaker":"安藤委員","text":"私も、いじめを受けた被害者の方やそのご家族の方などから、昨年度、複数、相談を結構受けまして、いろいろ大変な難しい問題だと思いながら相談に乗っているのですが、被害者の立場に立ち切って、学校や教育委員会が対応、調査できているのかというのは、少し検証が必要かと感じているのです。ただし、調査結果が一向に上がってこないので分からないのですが、先ほど６件が終了して、今、公表の可否を確認中ということで、そういう報告が３回ぐらい続いていると思うのです。現状、どうなっているのでしょうか。確認に手間取っているのか。いつぐらいに議会や、あるいは議会に報告した後にはホームページなどに掲載があるのでしょうか。その辺の現状について、もう少し教えてもらえることがあれば教えていただきたいと思います。"},{"i":175,"speaker":"丸谷教育総合支援センター長","text":"いじめの重大事態の調査結果、いわゆる答申が出た段階で、まずは被害児童・生徒のご家庭に調査結果をお送りしております。その上で、品川区いじめ対策委員会からの説明の希望の有無の確認、それから公表の希望の有無の確認というものを取っております。また、調査結果に対して意見がある場合には、意見書を添えることができます。そういった家庭からの返信を待って、まずは区長への報告を行っております。\n調査結果の公表を希望される場合には、事務局が品川区いじめ対策委員会の確認を取りながら、公表版を作成し、改めて被害児童・生徒の保護者に確認を取るという流れになってございます。公表版につきまして家庭の了解が得られたところで、区のホームページへ掲載するとともに、議会への報告を行うということで考えているところですけれども、家庭との調整にはやはり一定程度、時間を頂いておりまして、特に現在も当事者が区立学校に在籍しているケースになりますので、記載の内容については慎重に吟味しているところです。\n他自治体の手続を見てみても、最低でも、調査結果が出てから３か月、長いものですと１年程度、公表までにかかっているということで、こちらは他自治体の様子も見ていると、そういうことも分かってきておりますので、手続はしっかり手順を踏みながら、しっかりとやっていきたいと考えております。"},{"i":176,"speaker":"安藤委員","text":"分かりました。どの辺まで来ているものがあるのかというのは、今、大分、いろいろ確かにそうですよね。いろいろ手続は必要だと思うのですけれども、どの辺まで来ているものがどれぐらいあるのかというのは教えていただきたいのと、あと、重大事態も、昨年度は１２件あったということなのですけれども、重大事態の発生については、東京都あるいは国に対して、区は報告する仕組みはどうなっているのでしょうか。何件ありましたなどというのは、どのように、いつぐらいに報告し、それが発表されるのはいつなのでしょうか。それも併せて教えていただきたいと思います。"},{"i":177,"speaker":"丸谷教育総合支援センター長","text":"まず、調査が終わっている６件につきましては、それぞれ状態が違うのですけれども、今、公表版の作成が一通り終わって、保護者確認に入るという事案もございます。また、今、意見書を求めているケースなど、それぞれ結果が出た時期によって段階が違いますので、それぞれ進めていきたいと考えております。\nまた、都や国への報告についてなのですけれども、およそ１年前に国から、令和５年度分から、いじめの重大事態が発生した場合には国への報告というものが義務付けされました。発生した時点、また、本区で言うと品川区いじめ対策委員会での調査が始まった時点、それから調査結果が出た時点で、それぞれ都教育委員会経由で国には報告を上げることになっておりまして、その手続も瑕疵のないように進めているところでございます。\nまた国の、不登校等、問題行動の調査については、今、不登校の要因についての調査の仕方について、国のほうで見直しを図るということで、年度末、そういった報道もありましたけれども、現在、新しい報告様式というものを待っている段階でございます。例年ですと年度末から年度初めにかけて、いじめの件数や不登校の件数というものを、調査をかけて、都教育委員会に報告して、国に報告が上がって、その調査結果がまとまるのが大体秋口といったことで、国全体の重大事態の件数や、都道府県別の重大事態の数、いじめの認知件数といったものが出てくるという流れになってございます。"},{"i":178,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":179,"speaker":"ゆきた委員","text":"いじめの重大事態について、１１月の文教委員会では、いじめ防止対策推進条例の一部を改正する条例が審議され、いじめ対策委員会に臨時委員を置くことができるようになったと思われます。今年度の重大事態は１２件と報告があり、６件が調査中と、ただいまもお話があったとおり公開されていますが、現在のいじめ対策委員会は、この６件について何名体制で行われているのかお聞きできればと思います。"},{"i":180,"speaker":"丸谷教育総合支援センター長","text":"現在、昨年度中に臨時委員を１名、委嘱するような形で、これは事案ごとに委嘱して、事案が終わったら解嘱というような形になるのですけれども、事案が今、次々上がってきていますので、１名の方に複数の事案もお願いするということで、今進めています。法律家の専門家を１名追加しております。また、４月からは学識経験者も正式な委員として加わることになりましたので、現在、６名体制で、残りの６つの事案について調査を進めているということになります。"},{"i":181,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(7) 令和５年度 就学・転学相談の結果"},{"i":182,"speaker":"つる委員長","text":"次に、(7)令和５年度 就学・転学相談の結果を議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":183,"speaker":"唐澤特別支援教育担当課長","text":"私からは、令和５年度 就学・転学相談の結果についてご報告申し上げます。お手元の資料をご確認ください。\nまず目的ですが、お子さん一人一人の教育的ニーズに合った助言を基本理念とし、最も適した「学びの場」を保護者と相談しながら決めております。特別支援学校の入学、特別支援学級または通級指導学級・特別支援教室の利用をこの場で検討しているところです。\n続いて２番の「概要」でございますが、就学相談につきましては、５月３０日から受け付けを開始し、７月下旬から１月末まで就学相談を実施いたしました。転学相談につきましては、在籍する児童・生徒を対象に、それぞれ実施してきたところです。\n３番の「相談件数」をご覧ください。まず就学相談についてですが、令和４年度と比較して、昨年度は、小学校、中学校合わせて３３件の相談が増えておりました。続いて右側、転学・通級相談についてですが、転学相談につきましては、小学校、中学校合わせて３１件、通級相談につきましては６８件、件数が増加しておりました。最後、一番下段になりますが、昨年度の就学相談の児童・生徒の内訳となっております。例年、事務事業概要ではまとめて表しておりますが、こちらにつきましては、小学校、中学校、それぞれ就学相談を受けた結果を示しております。括弧書きで記載している特別支援教室・通級指導学級につきましては、通常の学級に在籍しながら受けているものですので、ここは括弧書きで示しているところです。"},{"i":184,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたら、ご発言願います。"},{"i":185,"speaker":"安藤委員","text":"こういった相談があれば受けたいという保護者は非常に多いと思うのですけれども、この相談の周知はどういうふうに行き渡っているのかというか、その辺は徹底されているのかというのをお伺いしたいと、あと特別支援学級などですと、ＷＩＳＣとか、そういう検査みたいなものが、判断に当たって必要だったりする場合があるかと思うのですが、なかなか何か月先まで予約がいっぱいでできません、大変だという状況があるというのを伺ったことがあるのですが、現在はどのような状況になっているのでしょうか。伺います。"},{"i":186,"speaker":"唐澤特別支援教育担当課長","text":"２つ、質問をいただきました。\nまず周知についてですけれども、ホームページまたは広報などで周知については行っております。さらに、説明会については実施しておりますので、療育機関や就学前教育の機関といったところに私どもからもご説明を申し上げて周知しているところでございます。\n続いて検査についてのご質問ですが、就学相談につきましては、新１年生については田中ビネー検査を実施しておりますが、こちらについては全数調査ができるように対応しております。\nご質問のＷＩＳＣ検査については、在籍児童・生徒を対象に行うところでございますが、おっしゃるとおり、回数には限度がございますので、利用相談の年間計画などを事前に周知し、それが適切に対応できるように、丁寧に学校にも説明しているところです。"},{"i":187,"speaker":"安藤委員","text":"周知の点では、ホームページと広報ということでは不十分ではないかと思うのですが、もっと充実させていく必要があると思います。何かお考えがあれば、直接、通知というかご案内を配るなどといったことも必要なのではないかと思うのですが、いかがでしょうか。"},{"i":188,"speaker":"唐澤特別支援教育担当課長","text":"すみません。説明が不十分で申し訳ないです。\nもちろん、例えば新７年生であれば、今現在、小学校・義務教育学校前期課程のほうに、様々、学校長連絡会などを通して周知もしますし、先ほど申し上げたとおり新１年生であれば、療育機関や就学前教育といったところの説明会なども実施していきますので、その場で丁寧にこれは説明できればと思っております。"},{"i":189,"speaker":"つる委員長","text":"ほかにございますか。よろしいですか。\nほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(8) （仮称）子ども・若者活動拠点基本構想について"},{"i":190,"speaker":"つる委員長","text":"次に、(8)（仮称）子ども・若者活動拠点基本構想についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":191,"speaker":"藤村子ども育成課長","text":"私からは、（仮称）子ども・若者活動拠点基本構想についてということで報言させていただきます。\nまず資料が、Ａ４が１枚と、Ａ３が１枚と、冊子ということで、３部構成になっておりますが、表紙のＡ４というところを中心に説明させていただきます。なお、本件につきましては、１月２２日の文教委員会で概略というか報告させていただいたところを、ブラッシュアップしたというようなものになっております。それで、基本構想というものが年度中に完成いたしましたので、改めて報告させていただいたという次第でございます。ですので重複する点もございますけれども、お聞きいただければと思います。\nまず、Ａ４紙の１枚目のところ、策定の目的として、こちらは資料の１枚目の１に記載のとおり、（仮称）子ども・若者活動拠点の整備に当たりまして、方向性の基礎となるものをということで策定したものでございます。\n２番に行きまして、検討経過といたしましては、令和４年度にお示しした「今後の児童センターの方向性」というところで出てきた課題等について、令和５年度にワークショップなどを行いまして、前回、委員から頂いた意見も踏まえて策定したというようなものになっております。\nまた次に、３の「基本構想の概要」というところになります。こちらは、こども基本法における「こども」という概念への支援というものを行うものといたしまして、児童センター機能というのを包含しながら、メインターゲットとしては、もう少し上の年齢層というところを目的にしているところです。そういったものを幅広く支援できるような施設にしたいと考えているところです。\nまた、児童センターとは異なる公の施設として、子ども・若者の主体性を尊重するとともに、地域のつながりなども得られるような施設としたいと考えております。\nまた、基本方針といたしましては、こちらは（２）のところに記載がございますけれども、居場所や活動機会の創出といったところ、ほか２点の合計４つを記載させていただいているような形になっております。\nまた、４番に行きまして、今後のスケジュールといたしましては、今年度、基本設計を行いまして、来年度、実施設計等、令和１０年度中の開設というのを目指すというような形になっております。\n続きまして資料の２枚目、Ａ３のところに簡単に触れたいと思うのですけれども、こちらのＡ３の資料は、冊子の概要というような形になっております。こちらにつきましても、１月の委員会での報告内容を少しブラッシュアップした形なので、あまり変わりはないところなのですが、一番変わっているというか、新たな情報を追加したというところが、右側の中段、第５章、「提供するプログラム・使い方に関する考え方」ですが、こちらについて少し詳しく、例えばプログラムの種類として、具体的なプログラム名で、こんなものが考えられるのではないかということで、まだ決定事項ではないのですけれども例を示したという形になっております。こういった形で具体的なものが上がってきたというところですので、冊子も後ほど併せてご確認いただければと思います。"},{"i":192,"speaker":"つる委員長","text":"説明が終わりました。\n本件に関しましてご質疑等がございましたらご発言願います。"},{"i":193,"speaker":"安藤委員","text":"すみませんが、Ａ４の縦の資料で、「施設の役割」というところで、こども基本法における「こども」と書いていますけれども、これは何を指すのか、どんな定義なのかお伺いしたいのと、あと、居場所ということで、非常にいいと思うのですけれども、現在、一応、フリースペースはあるのですけれども、そことの関連や、すみ分け、違いというのは何なのかというのをお伺いしたいと思います。"},{"i":194,"speaker":"藤村子ども育成課長","text":"「こども」の定義というところで、ご質問いただいたところからお答えいたします。\nこども基本法における「こども」というのが、心身の発達過程にある者ということで、こちらは年齢というのは明確に区分されていないような形になりますので、そういった概念を持って考えていきたいと考えているところです。\nまた、フリースペースの関係とすみ分けというところですが、こちらは以前、委員会でお答えしたところと変わっていないところなのですが、フリースペースは今、現状ある西品川のものはそのまま継続するという形で考えておりまして、フリースペースの出口的な要素を持つ形の施設にしていけたらいいと考えているところです。"},{"i":195,"speaker":"安藤委員","text":"分かりました。Ａ３の「概要」の第３章の、「施設のコンセプト」と書いていますけれども、とてもいいと思うのです。子ども・若者を主役にするということや、様々な体験、仲間や地域と接する機会の提供、あと自分らしくいられる居場所と。これは本当に、今の若い方々にとって必要なコンセプトなのではないかと思うのですけれども、これをさらに磨き上げる点では、施設整備に当たって、当事者の子どもと若者の意見をできる限り聞いて、それを反映させるという部分が非常に重要になってくるのではないかと思うのですけれども、これは、スケジュールもありますが、今年度は基本設計に入るということなのですが、具体的にはどういう仕組みで、当事者の子ども・若者の声を聞いて反映させていくのかという点をお伺いしたいのと、第６章の管理運営なのですけれども、これまで培った区の直営というのを存続していくことが必要なのではないかと私は思いますが、やはり児童センターで、地域で育てられたという経験を持っている品川区のお子さんが、今、子育て世代とか、この議会にも何人か来ているわけですけれども、やはりすごく、品川区の児童センターでの経験というのが肥やしになっているわけですから、私はこれは区の財産だと思うので、これをぜひ存続して、区としても、子ども・若者支援のノウハウというのを、きちんと区の中の職員の中で蓄積・継承していくということが必要だと思うのです。そうした意見を述べた上で、区が直営でいくということと、本文の冊子には、もう少し具体的に書いているのですけれども、３３ページなのですが、案１、案２と書いているのですけれども、区直営のメリットとデメリットを、現時点で品川区はどう考えているのか。私はメリットのほうが大きいし、それを活かしていくというところを、やはりやりたいものではないかと思うのですけれども、どうでしょうか。伺いたいと思います。"},{"i":196,"speaker":"藤村子ども育成課長","text":"３点ほどご質問いただいたかと思います。\nまず、当事者の声をどうやって聞いていくかというところですけれども、まず児童センターの日々の業務の中で、そういったお声が入ってくるというところも１点あると思いますが、子ども計画の策定をする中で、様々、当事者および保護者の意見というのを聞く機会がございますので、そういった声の中から、今回の施設に活かせるところを酌み取って、活かしていきたいと考えているところです。\nまた、管理運営を直営にしたほうがいいのではないかというところですけれども、こちらについては現在、検討中の事項なので、どういった形にするかというのは、今後、考えていきたいと思っているところです。また、児童センター機能については、引き続き包含していく形で検討しておりますので、そういった児童センターのエッセンスがなくなるということではないかと考えております。\nまた、委託のメリット・デメリット、直営のメリット・デメリットでもあると思うのですけれども、直営というところであれば、人材を育てていけるかというところはある一方で、民間のノウハウや新しい要素を組み込むという面においては、少し難しいところがあるのがデメリットかと思います。一般的に言うような指定管理のメリットやデメリットというところと同じなのかとは考えております。"},{"i":197,"speaker":"安藤委員","text":"そうですね。ぜひこれまで品川区の若者を育ててきた児童センターの歴史を踏まえた上で、それを大事にしていただきたいと思います。\nそれと１点、施設を整備するに当たっても、やはりその施設の設計や具体的な内容について当事者の意見を聞くというのはすごく大事だと思うので、日々の業務や、子ども計画という大きな計画策定の中で、いろいろ声は聞けると思うのですが、基本設計に当たっては、直接、その施設の中身についての意見も得られるような機会を、ぜひ設けていただきたいと思いますので、これは要望でございます。"},{"i":198,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":199,"speaker":"ゆきた委員","text":"基本構想の第５章では、「社会体験プログラムの実施」というところの記載がされていまして、若者が実際にこの施設で体験として働いていく環境が整う方向性であると思われます。第６章で、今、話が少しあった部分もあるのですけれども、運営案について記載もされていますが、スタッフの人材の確保という観点で、今後の方向性を少し詳しくお聞きできればと思います。"},{"i":200,"speaker":"藤村子ども育成課長","text":"スタッフの確保というところかと思いますが、こちらにつきましては、今後、運営形態を検討していく中で、直営であれば、そういった職員の人材確保をしていく必要があるかと思いますし、委託や指定管理ということであれば、しっかりそこに対応できるような業者を選定していきたいと考えております。"},{"i":201,"speaker":"ゆきた委員","text":"１月の文教委員会でも触れさせていただきましたが、スタッフの、働いている方々が、同じ若者が働いているということであれば、お兄さん、お姉さんであれば相談してみようというような、垣根が低くなってくると思われます。ハード面と同時に、やはり人が居場所として集まるのは、人の魅力によってや、同世代だなど共通のものを感じて、人は集まってくるのではないかと思われます。ぜひ、大学生などが働けるような人材の確保や、その人材の魅力の発信といったところで要望したいと思いますが、この辺についてお聞きできればと思います。"},{"i":202,"speaker":"藤村子ども育成課長","text":"若者というか、同じ目線でご相談や話ができるというところは、ひとつ大切なことかと思っておりますので、そういったスタッフの選考というか、考える際には、そういった要素も盛り込んでいきたいと思いますし、この施設を行う上で、ハードの部分というのも重要なのですけれども、ソフトの部分というところをどう発信していくか、活かしていくかというところが、この施設が成功できるかどうかというところの肝になってくるかと思いますので、情報発信などといったところは積極的にできるように、事前に計画は整えてまいりたいと思っております。"},{"i":203,"speaker":"ゆきた委員","text":"ぜひ、方向性として前向きに進めていただければと思います。"},{"i":204,"speaker":"つる委員長","text":"ほかにございますか。"},{"i":205,"speaker":"高橋（し）委員","text":"すみません。私の認識が少しあれだったのですが、そもそも子ども・若者活動拠点は児童センターという位置付けでいいのですか。条例上、この前、指定管理のあれで改正したと思うのですけれども、児童センターというたてつけの施設なのでしょうか。それだけ、すみません。"},{"i":206,"speaker":"藤村子ども育成課長","text":"決定事項ではないのですけれども、今のところ、児童センターの位置付けということではなくて、児童センター条例の枠から外れた新しい子ども・若者活動拠点という形で考えていきたいと考えております。"},{"i":207,"speaker":"高橋（し）委員","text":"ということは、それに関連した条例が出されてくるという理解でよろしいのでしょうか。子ども・若者活動拠点という施設がそうだという条例が、先の話になるのでしょうけれども、確認です。"},{"i":208,"speaker":"藤村子ども育成課長","text":"新規条例を上程するというような形の流れになるかと思います。"},{"i":209,"speaker":"つる委員長","text":"ほかにございますか。\nほかにご発言がないようですので、以上で本件および報告事項を終了いたします。\n────────────────────────────────────────────\n４ その他"},{"i":210,"speaker":"つる委員長","text":"次に、予定表４、その他を議題に供します。\nその他で何かございますでしょうか。\n〔「なし」と呼ぶ者あり〕"},{"i":211,"speaker":"つる委員長","text":"ないようですので、以上でその他を終了いたします。\n以上で、本日の予定は全て終了いたしました。これをもちまして、文教委員会を閉会いたします。\n○午後 ４時４９分閉会"}]});
